function FlowingMenu({
  items = [],
  speed = 60,
  direction = 'left',
  followCursor = 0.4,
  duration = 0.5,
  stretch = 0.6,
  magnet = 0.25,
  bandInset = 0,
  bandRadius = 0,
  carryContent = false,
  textColor = '#ffffff',
  bgColor = '#120F17',
  marqueeBgColor = '#ffffff',
  marqueeTextColor = '#120F17',
  borderColor = 'rgba(255, 255, 255, 0.14)',
  dividers = true,
  dimInactive = false,
  align = 'center',
  showIndex = false,
  showArrow = false,
  imageShape = 'pill',
  intro = true,
  activeIndex,
  onItemClick,
  ariaLabel = 'Menu',
  className = '',
  style
}: FlowingMenuProps) {
  const rootRef = useRef<HTMLElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const rows = useRef<Row[]>([]);
  const marquees = useRef<Marquee[]>([]);
  const metrics = useRef<(Metric | null)[]>([]);
  const band = useRef({
    top: 0,
    bottom: 0,
    vTop: 0,
    vBottom: 0,
    toTop: 0,
    toBottom: 0,
    lead: 1,
    shown: false,
    index: -1,
    rest: 0
  });
  const cursor = useRef<{ x: number; y: number | null; t: number; vx: number }>({ x: 0, y: null, t: 0, vx: 0 });
