  const kick = () => {
    const state = engine.current;
    if (state.raf || typeof window === 'undefined') return;
    state.last = performance.now();
    state.raf = requestAnimationFrame(frame);
  };

  const visibleCenter = () => {
    const root = rootRef.current;
    if (!root) return 0;
    const rect = root.getBoundingClientRect();
    const top = Math.max(0, -rect.top);
    const bottom = Math.min(rect.height, window.innerHeight - rect.top);
    return bottom > top ? (top + bottom) / 2 : rect.height / 2;
  };

  const flushReveals = () => {
    engine.current.flush = 0;
    const s = settingsRef.current;
    const batch: { id: string; spring: Spring }[] = [];
    pending.current.forEach(id => {
      const spring = springs.current.get(id);
      if (spring && !spring.shown) batch.push({ id, spring });
    });
    pending.current.clear();
    if (!batch.length) return;
    batch.sort((a, b) => a.spring.ty - b.spring.ty || a.spring.tx - b.spring.tx);
    const now = performance.now();
    const still = reduced() || s.animateFrom === 'none';
    const rootWidth = rootRef.current?.clientWidth ?? 0;
    const centerY = visibleCenter();
    batch.forEach(({ id, spring }, rank) => {
      spring.shown = true;
      spring.blur = s.blurToFocus && !still;
      if (still) {
        spring.x = spring.tx;
        spring.y = spring.ty;
        spring.s = 1;
        spring.reveal = 1;
        spring.start = now;
        paint(id, spring);
        return;
      }
      const direction =
        s.animateFrom === 'random' ? DIRECTIONS[Math.floor(Math.random() * DIRECTIONS.length)] : s.animateFrom;
      const distance = 60 + Math.min(spring.h, 280) * 0.35;
      spring.x = spring.tx;
      spring.y = spring.ty;
      spring.s = 0.96;
      if (direction === 'center') {
        spring.x = rootWidth / 2 - spring.w / 2;
        spring.y = centerY - spring.h / 2;
        spring.s = 0.55;
      } else if (direction === 'bottom') spring.y += distance;
      else if (direction === 'top') spring.y -= distance;
      else if (direction === 'left') spring.x -= distance;
      else if (direction === 'right') spring.x += distance;
      spring.vx = spring.vy = spring.vs = 0;
      spring.reveal = 0;
      spring.start = now + rank * s.stagger * 1000;
      paint(id, spring);
    });
    kick();
  };

  const requestReveal = (id: string) => {
    const spring = springs.current.get(id);
    if (!spring || spring.shown) return;
    if (!loaded.current.has(id)) {
      waiting.current.add(id);
      return;
    }
    waiting.current.delete(id);
    pending.current.add(id);
    if (!engine.current.flush) engine.current.flush = requestAnimationFrame(flushReveals);
  };

  const revealRef = useRef(requestReveal);
  revealRef.current = requestReveal;

  const markLoaded = (id: string) => {
    loaded.current.add(id);
    const node = nodes.current.get(id);
    node?.querySelector('img')?.setAttribute('data-loaded', '');
    if (waiting.current.has(id)) requestReveal(id);
  };

  useIsoLayoutEffect(() => {
    const previous = previousRef.current;
    const live = new Set(items.map(keyOf));
    const leaving: Ghost[] = [];
    previous.forEach((entry, id) => {
      if (live.has(id)) return;
      const spring = springs.current.get(id);
      previous.delete(id);
      if (!spring?.shown) return;
      leaving.push({ id, item: entry.item, x: spring.x, y: spring.y, s: spring.s, w: entry.w, h: entry.h });
      springs.current.delete(id);
    });
    if (leaving.length) setGhosts(current => [...current.filter(ghost => !live.has(ghost.id)), ...leaving]);
    setOrder(null);
  }, [itemsKey]);

  useIsoLayoutEffect(() => {
    if (!layout) return;
    const root = rootRef.current;
    const instant = reduced();
    layout.tiles.forEach(tile => {
      const node = nodes.current.get(tile.id);
      let spring = springs.current.get(tile.id);
      if (!spring) {
        spring = {
          x: tile.x,
          y: tile.y,
          s: 1,
          vx: 0,
          vy: 0,
          vs: 0,
          tx: tile.x,
          ty: tile.y,
          w: tile.w,
          h: tile.h,
          shown: false,
          dragging: false,
          blur: false,
          reveal: 0,
          start: 0
        };
        springs.current.set(tile.id, spring);
        if (node) {
          node.style.opacity = '0';
          node.style.transform = `translate3d(${tile.x}px, ${tile.y}px, 0)`;
        }
      } else if (spring.shown && Math.abs(spring.w - tile.w) > 0.5 && !instant) {
        spring.s *= spring.w / tile.w;
      }
      spring.tx = tile.x;
      spring.ty = tile.y;
      spring.w = tile.w;
      spring.h = tile.h;
      if (!spring.shown) {
        spring.x = tile.x;
        spring.y = tile.y;
        if (node) node.style.transform = `translate3d(${tile.x}px, ${tile.y}px, 0)`;
      } else if (instant && !spring.dragging) {
        spring.x = tile.x;
        spring.y = tile.y;
        spring.s = 1;
        paint(tile.id, spring);
      }
      previousRef.current.set(tile.id, { item: tile.item, w: tile.w, h: tile.h });
    });
    if (root) root.style.height = `${layout.height}px`;
    kick();
  });

  useEffect(() => {
    if (!layout) return undefined;
    const ids = layout.tiles.map(tile => tile.id);
    const reveal = revealRef.current;
    if (!settingsRef.current.revealOnScroll || typeof IntersectionObserver === 'undefined') {
      ids.forEach(reveal);
      return undefined;
    }
    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(entry => {
          if (!entry.isIntersecting) return;
          const id = entry.target.getAttribute('data-id');
          if (id) reveal(id);
          observer.unobserve(entry.target);
        });
      },
      { rootMargin: '0px 0px -6% 0px' }
    );
    ids.forEach(id => {
      const node = nodes.current.get(id);
      if (node && !springs.current.get(id)?.shown) observer.observe(node);
    });
    return () => observer.disconnect();
  }, [layout, revealOnScroll]);

  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];
    waiting.current.forEach(id => {
      timers.push(
        setTimeout(() => {
          if (!waiting.current.has(id)) return;
          loaded.current.add(id);
          revealRef.current(id);
        }, 2500)
      );
    });
    return () => timers.forEach(clearTimeout);
  }, [layout]);

  useEffect(() => {
    ghosts.forEach(ghost => {
      const node = ghostsRef.current.get(ghost.id);
      if (!node || node.getAttribute('data-leaving')) return;
      node.setAttribute('data-leaving', '');
      const from = `translate3d(${ghost.x}px, ${ghost.y}px, 0) scale(${ghost.s})`;
      const to = `translate3d(${ghost.x + ghost.w * 0.04}px, ${ghost.y + ghost.h * 0.04}px, 0) scale(${ghost.s * 0.92})`;
      const animation = node.animate(
        [
          { transform: from, opacity: 1 },
          { transform: to, opacity: 0 }
        ],
        { duration: reduced() ? 1 : 320, easing: 'cubic-bezier(0.4, 0, 1, 1)', fill: 'forwards' }
      );
      animation.finished
        .then(() => setGhosts(current => current.filter(entry => entry.id !== ghost.id)))
        .catch(() => {});
    });
  }, [ghosts]);

  useEffect(() => {
    const strength = settingsRef.current.parallax;
    const layers = () => [...nodes.current.values()].map(node => node.querySelector<HTMLElement>('[data-parallax]'));
    if (!strength || !layout) {
      layers().forEach(layer => {
        if (layer) layer.style.transform = '';
      });
      return undefined;
    }
    let raf = 0;
    const scroller = scrollerOf(rootRef.current);
    const update = () => {
      raf = 0;
      const frame = scroller ? scroller.getBoundingClientRect() : { top: 0, bottom: window.innerHeight };
      const top = Math.max(frame.top, 0);
      const bottom = Math.min(frame.bottom, window.innerHeight);
      const center = (top + bottom) / 2;
      nodes.current.forEach(node => {
        const layer = node.querySelector<HTMLElement>('[data-parallax]');
        if (!layer) return;
        const rect = node.getBoundingClientRect();
        if (rect.bottom < top - 200 || rect.top > bottom + 200) return;
        const reach = strength * 0.2 * rect.height;
        const shift = clamp(-(rect.top + rect.height / 2 - center) * strength * 0.25, -reach, reach);
        layer.style.transform = `translate3d(0, ${shift.toFixed(2)}px, 0) scale(${(1 + strength * 0.4 + 0.002).toFixed(3)})`;
      });
    };
    const schedule = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };
    update();
    window.addEventListener('scroll', schedule, { capture: true, passive: true });
    window.addEventListener('resize', schedule, { passive: true });
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('scroll', schedule, { capture: true });
      window.removeEventListener('resize', schedule);
    };
  }, [layout, parallax]);

  useEffect(() => {
    const state = engine.current;
    return () => {
      cancelAnimationFrame(state.raf);
      cancelAnimationFrame(state.flush);
    };
  }, []);

  const setDimmed = (activeId: string | null) => {
    nodes.current.forEach((node, id) => {
      if (activeId && id !== activeId) node.setAttribute('data-dimmed', '');
      else node.removeAttribute('data-dimmed');
    });
  };

  const onEnter = (id: string) => {
    if (settingsRef.current.focusOnHover && !dragRef.current?.active) setDimmed(id);
  };

  const onLeave = (event: ReactPointerEvent<HTMLElement>) => {
    if (settingsRef.current.focusOnHover) setDimmed(null);
    event.currentTarget.style.removeProperty('--masonry-tilt-x');
    event.currentTarget.style.removeProperty('--masonry-tilt-y');
  };

  const onTilt = (event: ReactPointerEvent<HTMLElement>) => {
    if (settingsRef.current.hoverEffect !== 'tilt' || dragRef.current?.active) return;
    const card = event.currentTarget;
    const rect = card.getBoundingClientRect();
    const px = (event.clientX - rect.left) / rect.width - 0.5;
    const py = (event.clientY - rect.top) / rect.height - 0.5;
    card.style.setProperty('--masonry-tilt-x', `${(-py * 10).toFixed(2)}deg`);
    card.style.setProperty('--masonry-tilt-y', `${(px * 10).toFixed(2)}deg`);
  };

  const finishDrag = () => {
    const drag = dragRef.current;
    window.removeEventListener('pointermove', moveDrag);
    window.removeEventListener('pointerup', finishDrag);
    window.removeEventListener('pointercancel', finishDrag);
    dragRef.current = null;
    if (!drag?.active) return;
    const spring = springs.current.get(drag.id);
    const node = nodes.current.get(drag.id);
    if (spring) spring.dragging = false;
    node?.removeAttribute('data-dragging');
    rootRef.current?.removeAttribute('data-dragging');
    suppressRef.current = true;
    setTimeout(() => {
      suppressRef.current = false;
    }, 0);
    kick();
    if (drag.moved) settingsRef.current.onReorder?.(orderedRef.current);
  };

  const moveDrag = (event: PointerEvent) => {
    const drag = dragRef.current;
    const root = rootRef.current;
    if (!drag || !root || event.pointerId !== drag.pointerId) return;
    if (!drag.active) {
      if (Math.hypot(event.clientX - drag.startX, event.clientY - drag.startY) < 6) return;
      const spring = springs.current.get(drag.id);
      if (!spring?.shown) return;
      drag.active = true;
      spring.dragging = true;
      spring.vx = spring.vy = spring.vs = 0;
      nodes.current.get(drag.id)?.setAttribute('data-dragging', '');
      root.setAttribute('data-dragging', '');
      setDimmed(null);
    }
    const rect = root.getBoundingClientRect();
    const spring = springs.current.get(drag.id);
    if (!spring) return;
    spring.x = event.clientX - rect.left - drag.offsetX;
    spring.y = event.clientY - rect.top - drag.offsetY;
    spring.s = 1;
    paint(drag.id, spring);
    kick();
    const list = orderedRef.current;
    const dragged = list.find(item => keyOf(item) === drag.id);
    const grid = paramsRef.current;
    if (!dragged || !grid.width) return;
    const others = list.filter(item => keyOf(item) !== drag.id);
    const slots = slotsFor(others, dragged, grid.width, grid.columns, grid.columnWidth, grid.gap, grid.measured);
    const cx = spring.x + spring.w / 2;
    const cy = spring.y + spring.h / 2;
    const current = list.indexOf(dragged);
    let best = current;
    let nearest = Math.hypot(slots[current].x - cx, slots[current].y - cy);
    const threshold = nearest * 0.8 - 6;
    slots.forEach((slot, index) => {
      const distance = Math.hypot(slot.x - cx, slot.y - cy);
      if (distance < nearest && distance < threshold) {
        nearest = distance;
        best = index;
      }
    });
    if (best === current) return;
    const ids = others.map(keyOf);
    ids.splice(best, 0, drag.id);
    drag.moved = true;
    setOrder(ids);
  };

  const startDrag = (event: ReactPointerEvent<HTMLElement>, id: string) => {
    const s = settingsRef.current;
    if (!s.draggable || event.button !== 0 || event.pointerType === 'touch' || openId) return;
    const root = rootRef.current;
    const spring = springs.current.get(id);
    if (!root || !spring) return;
    const rect = root.getBoundingClientRect();
    dragRef.current = {
      id,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      offsetX: event.clientX - rect.left - spring.x,
      offsetY: event.clientY - rect.top - spring.y,
      active: false,
      moved: false
    };
    window.addEventListener('pointermove', moveDrag);
    window.addEventListener('pointerup', finishDrag);
    window.addEventListener('pointercancel', finishDrag);
  };

  const onCardClick = (event: ReactMouseEvent<HTMLElement>, item: MasonryItem, index: number) => {
    if (suppressRef.current) {
      event.preventDefault();
      return;
    }
    const s = settingsRef.current;
    s.onItemClick?.(item, index, event);
    if (event.defaultPrevented) return;
    if (s.lightbox) {
      event.preventDefault();
      tokenRef.current += 1;
      setClosing(false);
      setOpenId(keyOf(item));
    }
  };

  const openIndex = openId ? ordered.findIndex(item => keyOf(item) === openId) : -1;
  const openItem = openIndex >= 0 ? ordered[openIndex] : null;

  const mediaRect = (id: string) =>
    nodes.current.get(id)?.querySelector('[data-media]')?.getBoundingClientRect() ?? null;

  const frameFor = (item: MasonryItem) => {
    const aspect = aspectOf(item, measured);
    const pad = window.innerWidth < 640 ? 16 : 72;
    const room = item.title || item.description || item.url ? 64 : 0;
    const maxW = Math.max(40, window.innerWidth - pad * 2);
    const maxH = Math.max(40, window.innerHeight - pad * 2 - room);
    let w = maxW;
    let h = w * aspect;
    if (h > maxH) {
      h = maxH;
      w = h / aspect;
    }
    const left = (window.innerWidth - w) / 2;
    const top = (window.innerHeight - room - h) / 2;
    return { left, top, width: w, height: h, room };
  };

  const closeBox = () => {
    if (!openId || closing) return;
    tokenRef.current += 1;
    const token = tokenRef.current;
    const box = boxRef.current;
    const image = box?.querySelector<HTMLElement>('[data-box-image]');
    const backdrop = box?.querySelector<HTMLElement>('[data-box-backdrop]');
    const rect = mediaRect(openId);
    setClosing(true);
    if (!image || !rect || reduced()) {
      setOpenId(null);
      setClosing(false);
      return;
    }
    const current = image.getBoundingClientRect();
    const scale = rect.width / current.width;
    image.getAnimations().forEach(animation => animation.cancel());
    const animation = image.animate(
      [
        { transform: 'none', borderRadius: '6px' },
        {
          transform: `translate(${rect.left - current.left}px, ${rect.top - current.top}px) scale(${scale})`,
          borderRadius: `${radius / Math.max(scale, 0.01)}px`
        }
      ],
      { duration: 380, easing: EASE, fill: 'forwards' }
    );
    backdrop?.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 300, easing: 'ease', fill: 'forwards' });
    box
      ?.querySelectorAll('[data-box-fade]')
      .forEach(node => node.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 160, fill: 'forwards' }));
    animation.finished
      .then(() => {
        if (token !== tokenRef.current) return;
        setOpenId(null);
        setClosing(false);
      })
      .catch(() => {});
  };

  const stepBox = (direction: number) => {
    if (!openItem || closing || ordered.length < 2) return;
    const next = ordered[(openIndex + direction + ordered.length) % ordered.length];
    setOpenId(keyOf(next));
  };

  useIsoLayoutEffect(() => {
    if (!openId) return undefined;
    const node = nodes.current.get(openId);
    node?.setAttribute('data-hidden', '');
    return () => node?.removeAttribute('data-hidden');
  }, [openId]);

  const openedRef = useRef<string | null>(null);
  useIsoLayoutEffect(() => {
    const box = boxRef.current;
    if (!openId || !box) {
      openedRef.current = null;
      return;
    }
    const image = box.querySelector<HTMLElement>('[data-box-image]');
    const backdrop = box.querySelector<HTMLElement>('[data-box-backdrop]');
    const fades = box.querySelectorAll('[data-box-fade]');
    if (!image) return;
    if (openedRef.current) {
      image.animate(
        [
          { opacity: 0, transform: 'scale(0.97)' },
          { opacity: 1, transform: 'none' }
        ],
        { duration: reduced() ? 1 : 320, easing: EASE }
      );
      openedRef.current = openId;
      return;
    }
    openedRef.current = openId;
    const rect = mediaRect(openId);
    const target = image.getBoundingClientRect();
    if (rect && !reduced()) {
      const scale = rect.width / target.width;
      image.animate(
        [
          {
            transform: `translate(${rect.left - target.left}px, ${rect.top - target.top}px) scale(${scale})`,
            borderRadius: `${radius / Math.max(scale, 0.01)}px`
          },
          { transform: 'none', borderRadius: '6px' }
        ],
        { duration: 520, easing: EASE }
      );
      backdrop?.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 360, easing: 'ease' });
      fades.forEach(fade =>
        fade.animate([{ opacity: 0 }, { opacity: 0, offset: 0.5 }, { opacity: 1 }], { duration: 560, easing: 'ease' })
      );
    }
  }, [openId]);

  if (openId) lastShownRef.current = openId;
  const isOpen = Boolean(openId);
  useEffect(() => {
    if (!isOpen) return undefined;
    const previous = document.documentElement.style.overflow;
    document.documentElement.style.overflow = 'hidden';
    boxRef.current?.querySelector<HTMLElement>('[data-box-close]')?.focus({ preventScroll: true });
    const map = nodes.current;
    return () => {
      document.documentElement.style.overflow = previous;
      map
        .get(lastShownRef.current ?? '')
        ?.querySelector<HTMLElement>('[data-card]')
        ?.focus({ preventScroll: true });
    };
  }, [isOpen]);

  useEffect(() => {
    if (!openId) return undefined;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') closeBox();
      else if (event.key === 'ArrowRight') stepBox(1);
      else if (event.key === 'ArrowLeft') stepBox(-1);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  });

  const captionMode = CAPTION_MODES.includes(captions) ? captions : 'hover';
  const mode = settings.hoverEffect;
  const box = openItem && typeof document !== 'undefined' ? frameFor(openItem) : null;

  return (
    <div
      ref={rootRef}
      className={[ROOT, className].filter(Boolean).join(' ')}
      style={{ '--masonry-radius': `${Math.max(0, radius)}px`, ...style } as CSSProperties}
      data-hover={mode}
      role="list"
    >
      {(layout?.tiles ?? []).map((tile, index) => {
        const { item } = tile;
        const id = tile.id;
        const label = item.title || item.alt || undefined;
        const shared = {
          className: CARD,
          'data-card': '',
          onClick: (event: ReactMouseEvent<HTMLElement>) => onCardClick(event, item, index),
          onPointerDown: (event: ReactPointerEvent<HTMLElement>) => startDrag(event, id),
          onPointerEnter: () => onEnter(id),
          onPointerLeave: onLeave,
          onPointerMove: onTilt
        };
        const content = (
          <span className={MEDIA} data-media="">
            <span className={PARALLAX} data-parallax="">
              <img
                className={IMAGE}
                src={item.img}
                alt={item.alt ?? item.title ?? ''}
                draggable={false}
                decoding="async"
                data-loaded={loaded.current.has(id) ? '' : undefined}
                ref={image => {
                  if (image?.complete && image.naturalWidth && !loaded.current.has(id)) markLoaded(id);
                }}
                onLoad={() => markLoaded(id)}
                onError={() => markLoaded(id)}
              />
            </span>
            {captionMode !== 'none' && (item.title || item.description) && (
              <span className={CAPTION} data-mode={captionMode}>
                {item.title && <span className={TITLE}>{item.title}</span>}
                {item.description && <span className={TEXT}>{item.description}</span>}
              </span>
            )}
          </span>
        );
        return (
          <div
            key={id}
            ref={node => {
              if (node) nodes.current.set(id, node);
              else nodes.current.delete(id);
            }}
            className={ITEM}
            style={{ width: tile.w, height: tile.h }}
            data-id={id}
            role="listitem"
          >
            {!lightbox && item.url ? (
              <a
                {...shared}
                href={item.url}
                target="_blank"
                rel="noopener noreferrer"
                draggable={false}
                aria-label={label}
              >
                {content}
              </a>
            ) : lightbox || onItemClick ? (
              <button {...shared} type="button" aria-label={label}>
                {content}
              </button>
            ) : (
              <div {...shared}>{content}</div>
            )}
          </div>
        );
      })}
      {ghosts.map(ghost => (
        <div
          key={`ghost-${ghost.id}`}
          ref={node => {
            if (node) ghostsRef.current.set(ghost.id, node);
            else ghostsRef.current.delete(ghost.id);
          }}
          className={GHOST}
          style={{
            width: ghost.w,
            height: ghost.h,
            transform: `translate3d(${ghost.x}px, ${ghost.y}px, 0) scale(${ghost.s})`
          }}
          aria-hidden="true"
        >
          <div className={MEDIA}>
            <img className={IMAGE} src={ghost.item.img} alt="" data-loaded="" draggable={false} />
          </div>
        </div>
      ))}
      {openItem &&
        box &&
        createPortal(
          <div
            ref={boxRef}
            className={BOX}
            role="dialog"
            aria-modal="true"
            aria-label={openItem.title || openItem.alt || 'Image'}
          >
            <div className={BOX_BACKDROP} data-box-backdrop="" onClick={closeBox} />
            <img
              className={BOX_IMAGE}
              data-box-image=""
              src={openItem.img}
              alt={openItem.alt ?? openItem.title ?? ''}
              draggable={false}
              style={{ width: box.width, height: box.height, left: box.left, top: box.top, borderRadius: 6 }}
              onClick={closeBox}
            />
            {box.room > 0 && (
              <div className={BOX_CAPTION} data-box-fade="" style={{ top: box.top + box.height + 18 }}>
                {openItem.title && <span>{openItem.title}</span>}
                {openItem.description && <span className={BOX_MUTED}>{openItem.description}</span>}
                {openItem.url && (
                  <a href={openItem.url} target="_blank" rel="noopener noreferrer">
                    Open
                    <HugeiconsIcon icon={ArrowUpRight01Icon} size={16} strokeWidth={2} />
                  </a>
                )}
              </div>
            )}
            <button
              type="button"
              className={BOX_CLOSE}
              data-box-fade=""
              data-box-close=""
              aria-label="Close"
              onClick={closeBox}
            >
              <HugeiconsIcon icon={Cancel01Icon} size={20} strokeWidth={2} />
            </button>
            {ordered.length > 1 && (
              <>
                <button
                  type="button"
                  className={BOX_PREV}
                  data-box-fade=""
                  aria-label="Previous"
                  onClick={() => stepBox(-1)}
                >
                  <HugeiconsIcon icon={ArrowLeft01Icon} size={20} strokeWidth={2} />
                </button>
                <button
                  type="button"
                  className={BOX_NEXT}
                  data-box-fade=""
                  aria-label="Next"
                  onClick={() => stepBox(1)}
                >
                  <HugeiconsIcon icon={ArrowRight01Icon} size={20} strokeWidth={2} />
                </button>
              </>
            )}
          </div>,
          document.body
        )}
    </div>
  );
};

export default Masonry;

'use client';

/* eslint-disable react/no-unknown-property */
import {
  Suspense,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
  type Ref,
  type RefObject
} from 'react';
import { Canvas, useFrame, useLoader, useThree } from '@react-three/fiber';
import { ContactShadows, Environment, useFBX, useGLTF } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader.js';
import * as THREE from 'three';

export type ModelViewerEnvironment =
  | 'apartment'
  | 'city'
  | 'dawn'
  | 'forest'
  | 'lobby'
  | 'night'
  | 'park'
  | 'studio'
  | 'sunset'
  | 'warehouse'
  | 'none';

export type ModelViewerIntro = 'rise' | 'spin' | 'fade' | 'none';

export interface ModelViewerHandle {
  capture: (type?: string) => string | null;
}

export interface ModelViewerProps {
  url: string;
  width?: number | string;
  height?: number | string;
  environment?: ModelViewerEnvironment;
  environmentIntensity?: number;
  exposure?: number;
  autoRotate?: boolean;
  autoRotateSpeed?: number;
  autoRotateDelay?: number;
  dragRotate?: boolean;
  turntable?: boolean;
  zoom?: boolean;
  minZoom?: number;
  maxZoom?: number;
  hoverTilt?: number;
  float?: number;
  shadow?: boolean;
  shadowOpacity?: number;
  intro?: ModelViewerIntro;
  startAngle?: number;
  tilt?: number;
  offsetX?: number;
  offsetY?: number;
  fit?: number;
  resetOnDoubleClick?: boolean;
  className?: string;
  style?: CSSProperties;
  onModelLoaded?: () => void;
  ref?: Ref<ModelViewerHandle>;
}

type Settings = {
  autoRotate: boolean;
  autoRotateSpeed: number;
  autoRotateDelay: number;
  dragRotate: boolean;
  turntable: boolean;
  zoom: boolean;
  minZoom: number;
  maxZoom: number;
  hoverTilt: number;
  float: number;
  shadow: boolean;
  shadowOpacity: number;
  intro: ModelViewerIntro;
  startAngle: number;
  tilt: number;
  offsetX: number;
  offsetY: number;
  fit: number;
  resetOnDoubleClick: boolean;
  reducedMotion: boolean;
};

type Bounds = { scale: number; center: THREE.Vector3; radius: number; floor: number };

type Motion = {
  yaw: number;
  pitch: number;
  yawVelocity: number;
  pitchVelocity: number;
  zoom: number;
  zoomGoal: number;
  tiltX: number;
  tiltY: number;
  tiltGoalX: number;
  tiltGoalY: number;
  spinSpeed: number;
  idle: number;
  dragging: boolean;
  intro: number;
  clock: number;
  reset: { yaw: number; pitch: number } | null;
};

type ModelProps = { url: string; children: (object: THREE.Object3D) => ReactNode };

const FOV = 30;
const INTRO_SECONDS = 1.3;
const DRAG_SPEED = 0.0065;
const PITCH_LIMIT = (65 * Math.PI) / 180;

const toRadians = (degrees: number) => (degrees * Math.PI) / 180;

const measured = new WeakMap<THREE.Object3D, Bounds>();
const announced = new WeakSet<THREE.Object3D>();

const measure = (object: THREE.Object3D): Bounds => {
  const cached = measured.get(object);
  if (cached) return cached;
  const box = new THREE.Box3().setFromObject(object);
  const extent = box.getSize(new THREE.Vector3());
  const center = box.getCenter(new THREE.Vector3());
  const scale = 2 / Math.max(extent.x, extent.y, extent.z, 0.0001);
  const bounds = { scale, center, radius: (extent.length() / 2) * scale, floor: (extent.y / 2) * scale };
  measured.set(object, bounds);
  return bounds;
};

const GltfModel = ({ url, children }: ModelProps) => {
  const { scene } = useGLTF(url, true, true);
  const object = useMemo(() => scene.clone(true), [scene]);
  return children(object);
};

const FbxModel = ({ url, children }: ModelProps) => {
  const fbx = useFBX(url);
  const object = useMemo(() => fbx.clone(true), [fbx]);
  return children(object);
};

const ObjModel = ({ url, children }: ModelProps) => {
  const obj = useLoader(OBJLoader, url);
  const object = useMemo(() => obj.clone(true), [obj]);
  return children(object);
};

const Model = ({ url, children }: ModelProps) => {
  const extension = (url.split('?')[0].split('.').pop() ?? '').toLowerCase();
  if (extension === 'fbx') return <FbxModel url={url}>{children}</FbxModel>;
  if (extension === 'obj') return <ObjModel url={url}>{children}</ObjModel>;
  return <GltfModel url={url}>{children}</GltfModel>;
};

const Exposure = ({ value }: { value: number }) => {
  const gl = useThree(state => state.gl);
  const invalidate = useThree(state => state.invalidate);
  useEffect(() => {
    gl.toneMapping = THREE.NeutralToneMapping;
    gl.toneMappingExposure = value;
    invalidate();
  }, [gl, value, invalidate]);
  return null;
};

const Refresh = () => {
  const invalidate = useThree(state => state.invalidate);
  useEffect(() => {
    invalidate();
  });
  return null;
};

const Lighting = ({ environment, intensity }: { environment: ModelViewerEnvironment; intensity: number }) => {
  const previous = useRef(environment);
  useEffect(() => {
    previous.current = environment;
  });
  const fallback =
    previous.current !== environment && previous.current !== 'none' ? (
      <Environment preset={previous.current} environmentIntensity={intensity} />
    ) : null;
  return (
    <Suspense fallback={fallback}>
      {environment !== 'none' && <Environment preset={environment} environmentIntensity={intensity} />}
      <Refresh />
    </Suspense>
  );
};

const Stage = ({
  object,
  settingsRef,
  visibleRef,
  onReady
}: {
  object: THREE.Object3D;
  settingsRef: RefObject<Settings>;
  visibleRef: RefObject<boolean>;
  onReady?: () => void;
}) => {
  const { camera, gl, size, invalidate } = useThree();
  const placeRef = useRef<THREE.Group>(null);
  const floatRef = useRef<THREE.Group>(null);
  const tiltRef = useRef<THREE.Group>(null);
  const spinRef = useRef<THREE.Group>(null);
  const fitRef = useRef<THREE.Group>(null);
  const bounds = useMemo(() => measure(object), [object]);
  const motionRef = useRef<Motion | null>(null);

  if (!motionRef.current) {
    const s = settingsRef.current;
    motionRef.current = {
      yaw: toRadians(s.startAngle),
      pitch: toRadians(s.tilt),
      yawVelocity: 0,
      pitchVelocity: 0,
      zoom: 1,
      zoomGoal: 1,
      tiltX: 0,
      tiltY: 0,
      tiltGoalX: 0,
      tiltGoalY: 0,
      spinSpeed: 0,
      idle: 0,
      dragging: false,
      intro: s.intro === 'none' ? 1 : 0,
      clock: 0,
      reset: null
    };
  }
  const motion = motionRef.current;

  useEffect(() => {
    if (announced.has(object)) return;
    announced.add(object);
    onReady?.();
  }, [object, onReady]);

  useEffect(() => {
    const element = gl.domElement;
    const pointers = new Map<number, { x: number; y: number; t: number }>();
    let pinchStart = 0;
    let zoomStart = 1;

    const wake = () => invalidate();

    const onDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      pointers.set(event.pointerId, { x: event.clientX, y: event.clientY, t: event.timeStamp });
      if (pointers.size === 2 && s.zoom) {
        const [a, b] = [...pointers.values()];
        pinchStart = Math.hypot(a.x - b.x, a.y - b.y);
        zoomStart = motion.zoomGoal;
        motion.dragging = false;
      } else if (pointers.size === 1 && s.dragRotate && (event.pointerType !== 'mouse' || event.button === 0)) {
        motion.dragging = true;
        motion.yawVelocity = 0;
        motion.pitchVelocity = 0;
        element.setPointerCapture?.(event.pointerId);
        element.style.cursor = 'grabbing';
      }
      motion.idle = 0;
      wake();
    };

    const onMove = (event: PointerEvent) => {
      const s = settingsRef.current;
      const rect = element.getBoundingClientRect();
      if (event.pointerType === 'mouse' || event.pointerType === 'pen') {
        const nx = ((event.clientX - rect.left) / rect.width) * 2 - 1;
        const ny = ((event.clientY - rect.top) / rect.height) * 2 - 1;
        motion.tiltGoalX = ny * s.hoverTilt * 0.6;
        motion.tiltGoalY = nx * s.hoverTilt;
      }
      const last = pointers.get(event.pointerId);
      if (last) {
        const dx = event.clientX - last.x;
        const dy = event.clientY - last.y;
        const elapsed = Math.max((event.timeStamp - last.t) / 1000, 1 / 240);
        last.x = event.clientX;
        last.y = event.clientY;
        last.t = event.timeStamp;
        if (pointers.size === 2 && s.zoom && pinchStart > 0) {
          const [a, b] = [...pointers.values()];
          const distance = Math.hypot(a.x - b.x, a.y - b.y);
          motion.zoomGoal = THREE.MathUtils.clamp((zoomStart * distance) / pinchStart, s.minZoom, s.maxZoom);
        } else if (motion.dragging) {
          const m = motion;
          m.yaw += dx * DRAG_SPEED;
          m.yawVelocity = m.yawVelocity * 0.4 + ((dx * DRAG_SPEED) / elapsed) * 0.6;
          if (!s.turntable) {
            m.pitch = THREE.MathUtils.clamp(m.pitch + dy * DRAG_SPEED, -PITCH_LIMIT, PITCH_LIMIT);
            m.pitchVelocity = m.pitchVelocity * 0.4 + ((dy * DRAG_SPEED) / elapsed) * 0.6;
          }
          m.idle = 0;
        }
      }
      wake();
    };

    const onUp = (event: PointerEvent) => {
      const last = pointers.get(event.pointerId);
      if (last && event.timeStamp - last.t > 80) {
        motion.yawVelocity = 0;
        motion.pitchVelocity = 0;
      }
      pointers.delete(event.pointerId);
      if (pointers.size < 2) pinchStart = 0;
      if (pointers.size === 0) {
        motion.dragging = false;
        element.style.cursor = '';
      }
      wake();
    };

    const onLeave = () => {
      motion.tiltGoalX = 0;
      motion.tiltGoalY = 0;
      wake();
    };

    const onWheel = (event: WheelEvent) => {
      const s = settingsRef.current;
      if (!s.zoom || !(event.ctrlKey || event.metaKey)) return;
      event.preventDefault();
      const m = motion;
      m.zoomGoal = THREE.MathUtils.clamp(m.zoomGoal * Math.exp(-event.deltaY * 0.01), s.minZoom, s.maxZoom);
      m.idle = 0;
      wake();
    };

    const onDoubleClick = () => {
      const s = settingsRef.current;
      if (!s.resetOnDoubleClick) return;
      const m = motion;
      const turns = Math.round((m.yaw - toRadians(s.startAngle)) / (Math.PI * 2));
      m.reset = { yaw: toRadians(s.startAngle) + turns * Math.PI * 2, pitch: toRadians(s.tilt) };
      m.zoomGoal = 1;
      m.yawVelocity = 0;
      m.pitchVelocity = 0;
      m.idle = 0;
      wake();
    };

    element.addEventListener('pointerdown', onDown);
    element.addEventListener('pointermove', onMove);
    element.addEventListener('pointerup', onUp);
    element.addEventListener('pointercancel', onUp);
    element.addEventListener('pointerleave', onLeave);
    element.addEventListener('wheel', onWheel, { passive: false });
    element.addEventListener('dblclick', onDoubleClick);
    return () => {
      element.removeEventListener('pointerdown', onDown);
      element.removeEventListener('pointermove', onMove);
      element.removeEventListener('pointerup', onUp);
      element.removeEventListener('pointercancel', onUp);
      element.removeEventListener('pointerleave', onLeave);
      element.removeEventListener('wheel', onWheel);
      element.removeEventListener('dblclick', onDoubleClick);
    };
  }, [gl, invalidate, settingsRef, motion]);

  useFrame((_, delta) => {
    const place = placeRef.current;
    const floatGroup = floatRef.current;
    const tiltGroup = tiltRef.current;
    const spinGroup = spinRef.current;
    if (!place || !floatGroup || !tiltGroup || !spinGroup) return;
    const s = settingsRef.current;
    const m = motion;
    const dt = Math.min(delta, 0.05);
    m.clock += dt;
    m.idle += dt;
    const reduce = s.reducedMotion;

    if (m.intro < 1) m.intro = reduce ? 1 : Math.min(1, m.intro + dt / INTRO_SECONDS);
    const eased = 1 - Math.pow(1 - m.intro, 3);

    if (m.reset) {
      m.yaw += (m.reset.yaw - m.yaw) * (1 - Math.exp(-dt * 7));
      m.pitch += (m.reset.pitch - m.pitch) * (1 - Math.exp(-dt * 7));
      if (Math.abs(m.reset.yaw - m.yaw) < 0.001 && Math.abs(m.reset.pitch - m.pitch) < 0.001) m.reset = null;
    } else if (!m.dragging) {
      const decay = Math.exp(-dt * 4.5);
      m.yaw += m.yawVelocity * dt;
      m.pitch = THREE.MathUtils.clamp(m.pitch + m.pitchVelocity * dt, -PITCH_LIMIT, PITCH_LIMIT);
      m.yawVelocity *= decay;
      m.pitchVelocity *= decay;
      if (s.turntable) m.pitch += (toRadians(s.tilt) - m.pitch) * (1 - Math.exp(-dt * 4));
    }

    const spinning = s.autoRotate && !reduce && !m.dragging && m.idle > s.autoRotateDelay;
    m.spinSpeed += ((spinning ? s.autoRotateSpeed : 0) - m.spinSpeed) * (1 - Math.exp(-dt * 2));
    m.yaw += m.spinSpeed * dt;

    m.zoom += (m.zoomGoal - m.zoom) * (1 - Math.exp(-dt * 8));
    m.tiltX += (m.tiltGoalX - m.tiltX) * (1 - Math.exp(-dt * 6));
    m.tiltY += (m.tiltGoalY - m.tiltY) * (1 - Math.exp(-dt * 6));

    const aspect = size.width / Math.max(size.height, 1);
    const halfView = Math.tan(toRadians(FOV) / 2);
    const fitDistance = bounds.radius / (Math.max(s.fit, 0.05) * halfView * Math.min(1, aspect));
    const distance = fitDistance / m.zoom;
    camera.position.set(0, 0, distance);
    camera.near = distance / 50;
    camera.far = distance * 50;
    camera.lookAt(0, 0, 0);
    camera.updateProjectionMatrix();

    const halfHeight = fitDistance * halfView;
    place.position.set(s.offsetX * halfHeight * aspect, s.offsetY * halfHeight, 0);

    const intro = s.intro;
    const rise = intro === 'rise' ? (1 - eased) * -0.45 : 0;
    const grow = intro === 'rise' ? 0.9 + 0.1 * eased : 1;
    const twist = intro === 'spin' ? (1 - eased) * -Math.PI * 1.2 : intro === 'rise' ? (1 - eased) * -0.5 : 0;
    const bob = reduce ? 0 : Math.sin(m.clock * 1.3) * s.float * 0.06;
    floatGroup.position.y = rise + bob;
    floatGroup.scale.setScalar(grow);
    tiltGroup.rotation.set(m.tiltX, m.tiltY, 0);
    spinGroup.rotation.set(m.pitch, m.yaw + twist, 0, 'YXZ');

    const settling =
      m.intro < 1 ||
      m.dragging ||
      !!m.reset ||
      Math.abs(m.yawVelocity) + Math.abs(m.pitchVelocity) > 0.0005 ||
      Math.abs(m.zoomGoal - m.zoom) > 0.0005 ||
      Math.abs(m.tiltGoalX - m.tiltX) + Math.abs(m.tiltGoalY - m.tiltY) > 0.0005 ||
      m.spinSpeed > 0.0005 ||
      (s.autoRotate && !reduce) ||
      (s.float > 0 && !reduce);
    if (settling && visibleRef.current) invalidate();
  });

  return (
    <group ref={placeRef}>
      <group ref={floatRef}>
        <group ref={tiltRef}>
          <group ref={spinRef}>
            <group
              ref={fitRef}
              scale={bounds.scale}
              position={[
                -bounds.center.x * bounds.scale,
                -bounds.center.y * bounds.scale,
                -bounds.center.z * bounds.scale
              ]}
            >
              <primitive object={object} />
            </group>
          </group>
        </group>
      </group>
      {settingsRef.current.shadow && (
        <ContactShadows
          position={[0, -bounds.floor - 0.08, 0]}
          opacity={settingsRef.current.shadowOpacity}
          scale={bounds.radius * 4}
          blur={2.6}
          far={bounds.floor * 2 + 0.5}
          resolution={512}
          color="#000000"
        />
      )}
    </group>
  );
};

const ModelViewer = ({
  url,
  width = 400,
  height = 400,
  environment = 'studio',
  environmentIntensity = 1,
  exposure = 1,
  autoRotate = true,
  autoRotateSpeed = 0.4,
  autoRotateDelay = 2,
  dragRotate = true,
  turntable = false,
  zoom = true,
  minZoom = 0.7,
  maxZoom = 2,
  hoverTilt = 0.15,
  float = 0.3,
  shadow = true,
  shadowOpacity = 0.45,
  intro = 'rise',
  startAngle = -30,
  tilt = 10,
  offsetX = 0,
  offsetY = 0,
  fit = 0.8,
  resetOnDoubleClick = true,
  className = '',
  style,
  onModelLoaded,
  ref
}: ModelViewerProps) => {
  const glRef = useRef<THREE.WebGLRenderer | null>(null);
  const invalidateRef = useRef<(() => void) | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const visibleRef = useRef(true);
  const [ready, setReady] = useState(false);
  const settings: Settings = {
    autoRotate,
    autoRotateSpeed,
    autoRotateDelay: Math.max(0, autoRotateDelay),
    dragRotate,
    turntable,
    zoom,
    minZoom: Math.min(minZoom, maxZoom),
    maxZoom: Math.max(minZoom, maxZoom),
    hoverTilt: Math.max(0, hoverTilt),
    float: Math.max(0, float),
    shadow,
    shadowOpacity,
    intro,
    startAngle,
    tilt,
    offsetX,
    offsetY,
    fit,
    resetOnDoubleClick,
    reducedMotion: typeof window !== 'undefined' && !!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  useImperativeHandle(
    ref,
    () => ({
      capture: (type = 'image/png') => glRef.current?.domElement.toDataURL(type) ?? null
    }),
    []
  );

  useEffect(() => {
    setReady(false);
  }, [url]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return undefined;
    const observer = new IntersectionObserver(entries => {
      visibleRef.current = entries.some(entry => entry.isIntersecting);
      if (visibleRef.current) invalidateRef.current?.();
    });
    observer.observe(container);
    return () => observer.disconnect();
  }, []);

  const handleReady = useCallback(() => {
    setReady(true);
    onModelLoaded?.();
  }, [onModelLoaded]);

  return (
    <div ref={containerRef} className={`relative ${className}`.trim()} style={{ width, height, ...style }}>
      <Canvas
        frameloop="demand"
        dpr={[1, 2]}
        camera={{ fov: FOV, position: [0, 0, 6], near: 0.01, far: 100 }}
        gl={{ antialias: true, alpha: true, preserveDrawingBuffer: true }}
        onCreated={state => {
          glRef.current = state.gl;
          invalidateRef.current = state.invalidate;
        }}
        style={{
          touchAction: 'pan-y',
          cursor: dragRotate ? 'grab' : 'default',
          opacity: ready || intro === 'none' ? 1 : 0,
          transition: intro === 'none' ? 'none' : 'opacity 0.6s ease'
        }}
      >
        <Exposure value={exposure} />
        <directionalLight position={[3, 5, 4]} intensity={0.6} />
        <Lighting environment={environment} intensity={environmentIntensity} />
        <Suspense fallback={null}>
          {url && (
            <Model url={url}>
              {object => (
                <Stage object={object} settingsRef={settingsRef} visibleRef={visibleRef} onReady={handleReady} />
              )}
            </Model>
          )}
        </Suspense>
      </Canvas>
    </div>
  );
};

export default ModelViewer;

