  };
  paintRef.current = paint;

  const localPoint = (cx: number, cy: number): [number, number] => {
    const b = (svgRef.current as SVGSVGElement).getBoundingClientRect();
    return [((cx - b.left) / b.width) * 200 - 100, ((cy - b.top) / b.height) * 200 - 100];
  };
