type Theme = 'dark' | 'light';
type Trigger = 'hover' | 'click';
type ClickHandler = (event: ReactMouseEvent<HTMLButtonElement> | PointerEvent) => void;

interface EngineProps {
  size: Size;
  altitude: number;
  hoverTime: number;
  jets: number;
  thrusters: boolean;
  trigger: Trigger;
  carryCursor: boolean;
  ramp: boolean;
  smoke: number;
  turbulence: number;
  wobble: number;
  thrustColor: string;
  smokeColor: string;
  theme: Theme;
  onClick?: ClickHandler;
}

interface EngineArgs {
  root: HTMLDivElement;
  canvas: HTMLCanvasElement;
  button: HTMLButtonElement;
  cursor: SVGSVGElement | null;
  ramp: SVGSVGElement | null;
  props: MutableRefObject<EngineProps>;
}

interface Engine {
  refresh: () => void;
  rehome: () => void;
  destroy: () => void;
}

interface RampGeo {
  ss: number[];
  xs: number[];
  ys: number[];
  ps: number[];
  ks: number[];
  r: number;
  T: number;
  x0: number;
  foot: number;
  S: number;
  clear: number;
  ok: boolean;
}

interface Track {
  geo: RampGeo;
  base: number;
  v0: number;
  acc: number;
}

interface Back {
  from: number;
  to: number;
  time: number;
}

interface Turn {
  th: number;
  w: number;
}

interface Piece {
  el: HTMLElement;
  x: number;
  y: number;
  k: number;
}

interface Strip {
  wrap: HTMLDivElement;
  ink: HTMLDivElement;
  parts: HTMLElement[];
