  fbo: WebGLFramebuffer | null;
  w: number;
  h: number;
  mips: boolean;
}

interface Pair {
  read: Target;
  write: Target;
  swap: () => void;
}

interface Program {
  p: WebGLProgram;
  u: Record<string, WebGLUniformLocation | null>;
}

type Uniform = number | number[] | Float32Array | Target | { f1: number[] };

interface Jets {
  a: Float32Array;
  b: Float32Array;
  bend: number[];
}

interface SimShared {
  jets: Jets;
  craft: number[];
  motion: number[];
  scale: number;
  activity: number;
  time: number;
}

interface StepInput extends SimShared {
  jetX: number[];
  jetN: number;
  spacing: number;
  calm: number;
