  sm: { height: 36, font: 13, icon: 14, px: 16 },
  md: { height: 44, font: 14, icon: 15, px: 20 },
  lg: { height: 52, font: 15, icon: 17, px: 24 }
};

const FuseButton: React.FC<FuseButtonProps> = ({
  label = 'Archive',
  undoLabel = 'Undo',
  doneLabel = 'Archived',
