  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hitRef = useRef<HTMLButtonElement>(null);
  const resetRef = useRef<(() => void) | null>(null);
  const cancelRef = useRef<(() => void) | null>(null);
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading');
  const options = useRef({
    releaseBehavior,
    crumpleAmount,
    crumpleDuration,
    releaseDuration,
    creaseStrength,
    draggable,
    dragRotation,
    dragRadius,
    returnToOrigin,
    disabled,
    onStateChange,
    onError
  });
  options.current = {
    releaseBehavior,
    crumpleAmount,
    crumpleDuration,
    releaseDuration,
    creaseStrength,
    draggable,
    dragRotation,
    dragRadius,
    returnToOrigin,
    disabled,
    onStateChange,
    onError
