    const canHover = Boolean(window.matchMedia?.('(hover: hover) and (pointer: fine)').matches);
    const drifting = liveEnabled && trail === 'auto';
    const scrolling = liveEnabled && trail === 'scroll';
    const following = liveEnabled && canHover && !scrolling;
    const driftSpacing = 0.12 + safeLag * 1.1;
    const burstReach = clamp(safeOffset / 36, 0.35, 2.5);
    const shiftLimit = safeOffset * 4;

    const state = {
      targetX: 0,
      targetY: 0,
      lastTargetX: 0,
      lastTargetY: 0,
      activity: entranceEnabled ? 1 : 0,
      positions: Array.from({ length: echoCount + 1 }, (_, index) => {
        const entranceAmount = entranceEnabled ? safeOffset * (index + 0.35) : 0;
        return { x: vector.x * entranceAmount, y: vector.y * entranceAmount };
      }),
      bends: Array.from({ length: echoCount + 1 }, () => ({ x: 0, y: 0 })),
      startTime: performance.now(),
      lastTime: 0,
      drift: 0,
      phase: 0,
      pointerNear: false,
      pointerTime: -Infinity,
      visible: true,
      pushX: 0,
      pushY: 0,
      velocityX: 0,
      velocityY: 0,
      bursts: [] as Burst[]
    };
    let frame = 0;

    for (let index = 1; index <= echoCount; index += 1) {
      const copy = copyRefs.current[index];
      if (copy) copy.style.filter = safeBlur > 0 ? `blur(${((safeBlur * index) / echoCount).toFixed(2)}px)` : 'none';
    }

    const renderBursts = (now: number) => {
      state.bursts = state.bursts.filter(burst => {
        const age = now - burst.start;
        let alive = false;

        burst.nodes.forEach((node, index) => {
          const local = (age - index * BURST_GAP) / BURST_LIFE;
          if (local < 1) alive = true;

          const progress = clamp(local, 0, 1);
          const spread = 1 - Math.pow(1 - progress, 3);
          const scale = 1 + spread * 0.34 * burstReach;
          const peak = 0.75 * Math.pow(safeFade, index * 0.5);
          const opacity = local <= 0 ? 0 : Math.min(1, progress * 8) * Math.pow(1 - progress, 1.5) * peak;

          node.style.transform = `translate3d(${burst.x.toFixed(2)}px, ${burst.y.toFixed(2)}px, 0) scale(${scale.toFixed(4)})`;
          node.style.opacity = opacity.toFixed(3);
          node.style.filter = safeBlur > 0 ? `blur(${(safeBlur * 0.3 * spread).toFixed(2)}px)` : 'none';
        });

        if (!alive) burst.nodes.forEach(node => node.remove());
        return alive;
      });
    };

    const renderFrame = (now: number) => {
      frame = 0;

      const dt = state.lastTime ? clamp(now - state.lastTime, 0, 64) : 16.67;
      const step = dt / 16.67;
      state.lastTime = now;

      const elapsed = now - state.startTime;
      const entranceProgress = entranceEnabled && safeDuration > 0 ? clamp(elapsed / safeDuration, 0, 1) : 1;
      const entranceRest = entranceEnabled ? 1 - easeFn(entranceProgress) : 0;
      const targetVelocity = Math.hypot(state.targetX - state.lastTargetX, state.targetY - state.lastTargetY);

      state.lastTargetX = state.targetX;
      state.lastTargetY = state.targetY;

      if (drifting) {
        const away = !following || !state.pointerNear || now - state.pointerTime > DRIFT_IDLE;
        state.drift += ((away ? 1 : 0) - state.drift) * (1 - Math.pow(0.965, step));
        state.phase += (dt / DRIFT_PERIOD) * Math.PI * 2;
      }

      if (scrolling) {
        const blend = 1 - Math.pow(0.7, step);
        state.velocityX += (state.pushX / Math.max(step, 0.25) - state.velocityX) * blend;
        state.velocityY += (state.pushY / Math.max(step, 0.25) - state.velocityY) * blend;
        state.pushX = 0;
        state.pushY = 0;
      }

      const speed = Math.hypot(state.velocityX, state.velocityY);
      const shiftX = clamp(-state.velocityX * 3.2, -shiftLimit, shiftLimit);
      const shiftY = clamp(-state.velocityY * 3.2, -shiftLimit, shiftLimit);
      const followX = state.targetX * (1 - state.drift);
      const followY = state.targetY * (1 - state.drift);

      let maxSeparation = 0;
      let maxGap = 0;

      for (let index = 0; index <= echoCount; index += 1) {
        const copy = copyRefs.current[index];
        const current = state.positions[index];
        const bend = state.bends[index];
        if (!copy || !current || !bend) continue;

        const depth = echoCount ? index / echoCount : 0;
        const entranceAmount = entranceRest * safeOffset * (index + 0.35);
        let desiredX = followX + vector.x * entranceAmount;
        let desiredY = followY + vector.y * entranceAmount;

        if (state.drift > 0.0005) {
          const phase = state.phase - index * driftSpacing;
          const swing = safeOffset * state.drift * (0.25 + 0.75 * depth);
          desiredX += Math.sin(phase) * swing;
          desiredY += Math.sin(phase) * Math.cos(phase) * swing * 1.3;
        }

        const lerp = 1 - Math.pow(1 - clamp(0.34 / (1 + index * safeLag * 4.2), 0.018, 0.36), step);
        const bendLerp = 1 - Math.pow(1 - 0.3 / (1 + depth * (1 + safeLag * 8)), step);

        current.x += (desiredX - current.x) * lerp;
        current.y += (desiredY - current.y) * lerp;
        bend.x += (shiftX * depth - bend.x) * bendLerp;
        bend.y += (shiftY * depth - bend.y) * bendLerp;
        maxGap = Math.max(
          maxGap,
          Math.abs(desiredX - current.x),
          Math.abs(desiredY - current.y),
          Math.abs(shiftX * depth - bend.x),
          Math.abs(shiftY * depth - bend.y)
        );

        const x = current.x + bend.x;
        const y = current.y + bend.y;
        const scale = 1 + (safeScale - 1) * depth;
        copy.style.transform = `translate3d(${x.toFixed(3)}px, ${y.toFixed(3)}px, 0) scale(${scale.toFixed(4)})`;

        if (index > 0) {
          const front = state.positions[0];
          maxSeparation = Math.max(maxSeparation, Math.hypot(x - front.x, y - front.y));
        }
      }

      const separationActivity = safeOffset > 0 ? clamp(maxSeparation / (safeOffset * 2.25), 0, 1) : 0;
      const targetActivity = safeOffset > 0 ? clamp(targetVelocity / (safeOffset * 0.35), 0, 1) : 0;
      const nextActivity = Math.max(
        entranceRest,
        separationActivity,
        targetActivity,
        state.drift * 0.9,
        clamp(speed / 5, 0, 1)
      );
      state.activity += (nextActivity - state.activity) * (1 - Math.pow(0.82, step));

      renderBursts(now);

      const running =
        entranceProgress < 1 ||
        state.activity > 0.002 ||
        maxGap > 0.05 ||
        speed > 0.02 ||
        state.bursts.length > 0 ||
        (drifting && state.visible);
      if (!running) state.activity = 0;

      for (let index = 1; index <= echoCount; index += 1) {
        const copy = copyRefs.current[index];
        if (copy) copy.style.opacity = String(Math.pow(safeFade, index) * state.activity);
      }

      if (running) frame = requestAnimationFrame(renderFrame);
    };

    const wake = () => {
      if (!frame) {
        state.lastTime = 0;
        frame = requestAnimationFrame(renderFrame);
      }
    };

    const handlePointerMove = (event: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      if (!rect.width || !rect.height) return;

      const deltaX = event.clientX - (rect.left + rect.width / 2);
      const deltaY = event.clientY - (rect.top + rect.height / 2);
      const distance = Math.hypot(deltaX, deltaY);
      const reach = distance > 0 ? clamp(distance / safeCursorRadius, 0, 1) : 0;
      const dirX = distance > 0 ? deltaX / distance : 0;
      const dirY = distance > 0 ? deltaY / distance : 0;

      state.targetX = dirX * reach * safeOffset;
      state.targetY = dirY * reach * safeOffset * 0.72;
      state.pointerNear = distance <= safeCursorRadius;
      state.pointerTime = performance.now();
      wake();
    };

    const handlePointerOut = (event: PointerEvent) => {
      if (event.relatedTarget) return;
      state.targetX = 0;
      state.targetY = 0;
      state.pointerNear = false;
      wake();
    };

    const scrollMemory = new WeakMap<Document | Element, [number, number]>();

    const handleScroll = (event: Event) => {
      const target = event.target;
      if (!(target instanceof Document) && !(target instanceof Element && target.contains(root))) return;

      const [x, y] = readScroll(target);
      const last = scrollMemory.get(target);
      scrollMemory.set(target, [x, y]);
      if (!last) return;

      state.pushX -= x - last[0];
      state.pushY -= y - last[1];
      wake();
    };

    const handleClick = (event: MouseEvent) => {
      const layer = burstRef.current;
      const rect = root.getBoundingClientRect();
      if (!layer || !echoCount || !rect.width || !rect.height) return;

      const originX = clamp((event.clientX - rect.left) / rect.width, 0, 1) * 100;
      const originY = clamp((event.clientY - rect.top) / rect.height, 0, 1) * 100;
      const count = clamp(Math.round(echoCount / 3) + 2, 3, 6);
      const front = state.positions[0];
      const nodes: HTMLElement[] = [];

      for (let index = 0; index < count; index += 1) {
        const source = copyRefs.current[1 + Math.round((index / Math.max(1, count - 1)) * (echoCount - 1))];
        if (!source) continue;
        const node = source.cloneNode(true) as HTMLSpanElement;
        node.removeAttribute('data-echo-index');
        node.style.transformOrigin = `${originX.toFixed(1)}% ${originY.toFixed(1)}%`;
        node.style.opacity = '0';
        layer.appendChild(node);
        nodes.push(node);
      }

      state.bursts.push({ start: performance.now(), x: front?.x || 0, y: front?.y || 0, nodes });
      while (state.bursts.length > 4) state.bursts.shift()?.nodes.forEach(node => node.remove());
      wake();
    };

    if (following) {
      window.addEventListener('pointermove', handlePointerMove, { passive: true });
      document.addEventListener('pointerout', handlePointerOut);
    }

    if (scrolling) {
      scrollMemory.set(document, readScroll(document));
      for (let node = root.parentElement; node; node = node.parentElement) scrollMemory.set(node, readScroll(node));
      document.addEventListener('scroll', handleScroll, { capture: true, passive: true });
    }

    if (clickBurst) root.addEventListener('click', handleClick);

    let observer: IntersectionObserver | undefined;
    if (drifting && typeof IntersectionObserver !== 'undefined') {
      observer = new IntersectionObserver(entries => {
        state.visible = entries[entries.length - 1].isIntersecting;
        if (state.visible) wake();
      });
      observer.observe(root);
    }

    renderFrame(state.startTime);

    return () => {
      cancelAnimationFrame(frame);
      window.removeEventListener('pointermove', handlePointerMove);
      document.removeEventListener('pointerout', handlePointerOut);
      document.removeEventListener('scroll', handleScroll, { capture: true });
      root.removeEventListener('click', handleClick);
      observer?.disconnect();
      state.bursts.forEach(burst => burst.nodes.forEach(node => node.remove()));
    };
  }, [
    blur,
    clickBurst,
    cursorRadius,
    direction,
    duration,
    ease,
    echoCount,
    echoScale,
    fade,
    lag,
    mode,
    offset,
    prefersReducedMotion,
    trail
  ]);

  const rootStyle: CSSProperties = {
    fontSize,
    fontWeight,
    color,
    cursor: canBurst ? 'pointer' : undefined,
    ...style
  };

  const echoClassName = [
    'pointer-events-none absolute inset-0 block origin-center transform-gpu backface-hidden will-change-[transform,opacity] motion-reduce:hidden',
    echoStyle === 'outline'
      ? '[-webkit-text-fill-color:transparent] [-webkit-text-stroke:max(1px,0.014em)_currentColor]'
      : ''
  ]
    .join(' ')
    .trim();

  return (
    <span
      ref={rootRef}
      className={`relative inline-block whitespace-nowrap select-none leading-[0.9] tracking-[-0.04em] [contain:layout_style] [font-kerning:normal] [text-rendering:geometricPrecision] ${className}`.trim()}
      style={rootStyle}
    >
      {echoIndexes.map(index => (
        <span
          aria-hidden="true"
          className={echoClassName}
          data-echo-index={index}
          key={`echo-${index}`}
          ref={element => {
            copyRefs.current[index] = element;
          }}
          style={{ color: echoColor(index), opacity: 0 }}
        >
          {text}
        </span>
      ))}
      <span aria-hidden="true" className="pointer-events-none absolute inset-0" ref={burstRef} />
      <span
        className="pointer-events-none relative z-[2] block transform-gpu text-shadow-[0_0.035em_0_rgba(255,255,255,0.04)] will-change-transform motion-reduce:[transform:none]!"
        data-echo-index="0"
        ref={element => {
          copyRefs.current[0] = element;
        }}
      >
        {text}
      </span>
    </span>
  );
};

export default EchoText;

'use client';

import { Fragment, useEffect, useMemo, useRef, type CSSProperties } from 'react';
import Matter from 'matter-js';

interface FallingTextProps {
  text?: string;
  highlightWords?: string[];
  highlightClass?: string;
  trigger?: 'auto' | 'hover' | 'click' | 'scroll';
  variant?: 'text' | 'tiles';
  split?: 'words' | 'letters';
  gravity?: number;
  bounciness?: number;
  scatter?: number;
  stagger?: number;
  order?: 'random' | 'sequence' | 'center' | 'together';
  draggable?: boolean;
  mouseConstraintStiffness?: number;
  cursorPush?: number;
  restoreDelay?: number;
  fontSize?: string;
  accentColor?: string;
  theme?: 'dark' | 'light';
  backgroundColor?: string;
  wireframes?: boolean;
  className?: string;
  style?: CSSProperties;
}

interface Piece {
  element: HTMLElement;
  body: Matter.Body;
  w: number;
  h: number;
  x0: number;
  y0: number;
  px: number;
  py: number;
  pa: number;
  dx: number;
  dy: number;
  da: number;
  at: number;
  released: boolean;
  knocked?: boolean;
  pushed?: number;
}

const THEMES: Record<string, Record<string, string>> = {
  dark: {
    '--falling-text-tile': 'linear-gradient(180deg, #3a3644 0%, #27242f 100%)',
    '--falling-text-tile-edge': 'rgba(255, 255, 255, 0.07)',
    '--falling-text-tile-highlight': 'rgba(255, 255, 255, 0.12)',
    '--falling-text-tile-shadow': '0 4px 10px -4px rgba(0, 0, 0, 0.7)',
    '--falling-text-tile-ink': '#f4f4f5'
  },
  light: {
    '--falling-text-tile': 'linear-gradient(180deg, #ffffff 0%, #f6f6f8 100%)',
    '--falling-text-tile-edge': 'rgba(24, 24, 27, 0.08)',
    '--falling-text-tile-highlight': 'rgba(255, 255, 255, 1)',
    '--falling-text-tile-shadow': '0 4px 10px -5px rgba(24, 24, 27, 0.25)',
    '--falling-text-tile-ink': '#27272a'
  }
};

const STEP = 1000 / 120;
const WALL = 400;
const SPRING =
  'linear(0, 0.0603, 0.2033, 0.3821, 0.5633, 0.7258, 0.8584, 0.9574, 1.0242, 1.0634, 1.0809, 1.0828, 1.0747, 1.0613, 1.046, 1.0313, 1.0186, 1.0085, 1.0012, 0.9965, 0.994, 0.9931, 0.9933, 0.9941, 0.9953, 0.9966, 0.9978, 0.9988, 1)';

const ROOT_CLASS =
  'relative box-border flex h-full w-full items-center justify-center overflow-hidden select-none [-webkit-tap-highlight-color:transparent] data-[dragging]:cursor-grabbing [&[data-trigger=click]:not([data-phase])]:cursor-pointer';
const TEXT_CLASS = 'box-border max-w-full p-[1em] text-center leading-[1.4] text-balance';
const PIECE_CLASS =
  'inline-block whitespace-pre data-[highlight]:font-semibold in-data-[phase]:will-change-transform [[data-draggable][data-phase=falling]:not([data-dragging])_&]:cursor-grab [[data-draggable][data-phase=falling]_&]:touch-none [[data-dragging]_&]:cursor-grabbing';
const PIECE_TEXT_CLASS = 'data-[highlight]:text-[color:var(--falling-text-accent)]';
const PIECE_TILE_CLASS =
  'mx-[0.06em] my-[0.14em] rounded-[0.42em] px-[0.56em] py-[0.24em] leading-[1.2] text-[color:var(--falling-text-tile-ink)] [background:var(--falling-text-tile)] [box-shadow:inset_0_0_0_1px_var(--falling-text-tile-edge),inset_0_1px_0_var(--falling-text-tile-highlight),var(--falling-text-tile-shadow)] data-[highlight]:text-[color:var(--falling-text-accent-ink)] data-[highlight]:[background:var(--falling-text-accent)] data-[highlight]:[box-shadow:inset_0_1px_0_rgba(255,255,255,0.24),var(--falling-text-tile-shadow)]';
const WIREFRAME_CLASS = 'outline -outline-offset-1 outline-current';

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

const readableOn = (color: string) => {
  let hex = String(color || '')
    .trim()
    .replace('#', '');
  if (hex.length === 3) hex = hex.replace(/./g, c => c + c);
  if (!/^[0-9a-f]{6}$/i.test(hex)) return '#ffffff';
  const [r, g, b] = [0, 2, 4].map(index => {
    const c = parseInt(hex.slice(index, index + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 0.4 ? '#18181b' : '#ffffff';
};

const springEase = () =>
  typeof CSS !== 'undefined' && CSS.supports?.('transition-timing-function', 'linear(0, 1)')
    ? SPRING
    : 'cubic-bezier(0.34, 1.4, 0.64, 1)';

const FallingText = ({
  text = '',
  highlightWords = [],
  highlightClass = 'highlighted',
  trigger = 'auto',
  variant = 'text',
  split = 'words',
  gravity = 1,
  bounciness = 0.2,
  scatter = 0.5,
  stagger = 0.03,
  order = 'random',
  draggable = true,
  mouseConstraintStiffness = 0.2,
  cursorPush = 0.5,
  restoreDelay = 0,
  fontSize = '1rem',
  accentColor = '#5b8cff',
  theme = 'dark',
  backgroundColor = 'transparent',
  wireframes = false,
  className = '',
  style
}: FallingTextProps) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);
  const settings = {
    trigger,
    gravity,
    bounciness,
    scatter,
    stagger,
    order,
    draggable,
    mouseConstraintStiffness,
    cursorPush,
    restoreDelay
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  const highlightKey = highlightWords.join('\u0000');
  const groups = useMemo(() => {
    const marks = highlightKey ? highlightKey.split('\u0000') : [];
    return String(text)
      .split(/\s+/)
      .filter(Boolean)
      .map(word => ({ word, highlighted: marks.some(entry => entry && word.startsWith(entry)) }));
  }, [text, highlightKey]);

  useEffect(() => {
    const container = containerRef.current;
    const block = textRef.current;
    if (!container || !block) return;
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let phase: 'idle' | 'falling' | 'restoring' = 'idle';
    let engine: Matter.Engine | null = null;
    let pieces: Piece[] = [];
    let walls: Matter.Body[] = [];
    let drag: { constraint: Matter.Constraint; id: number } | null = null;
    let raf = 0;
    let last = 0;
    let clock = 0;
    let accumulator = 0;
    let quietSince: number | null = null;
    let inside = false;
    let visible = true;
    let armed = true;
    let lastBounciness: number | null = null;
    const pointer = { x: 0, y: 0, vx: 0, vy: 0, time: 0 };

    const local = (event: PointerEvent) => {
      const box = container.getBoundingClientRect();
      return { x: event.clientX - box.left - container.clientLeft, y: event.clientY - box.top - container.clientTop };
    };

    const placeWalls = () => {
      if (!engine) return;
      const width = container.clientWidth;
      const height = container.clientHeight;
      const [floor, left, right, ceiling] = walls;
      Matter.Body.setPosition(floor, { x: width / 2, y: height + WALL / 2 });
      Matter.Body.setPosition(left, { x: -WALL / 2, y: height / 2 });
      Matter.Body.setPosition(right, { x: width + WALL / 2, y: height / 2 });
      Matter.Body.setPosition(ceiling, { x: width / 2, y: -WALL / 2 });
      pieces.forEach(piece => Matter.Sleeping.set(piece.body, false));
    };

    const draw = (alpha: number) => {
      for (const piece of pieces) {
        const { body } = piece;
        const x = piece.px + (body.position.x - piece.px) * alpha;
        const y = piece.py + (body.position.y - piece.py) * alpha;
        const angle = piece.pa + (body.angle - piece.pa) * alpha;
        if (Math.abs(x - piece.dx) < 0.01 && Math.abs(y - piece.dy) < 0.01 && Math.abs(angle - piece.da) < 0.0001)
          continue;
        piece.dx = x;
        piece.dy = y;
        piece.da = angle;
        piece.element.style.transform = `translate3d(${(x - piece.w / 2).toFixed(2)}px, ${(y - piece.h / 2).toFixed(2)}px, 0) rotate(${angle.toFixed(4)}rad)`;
      }
    };

    const release = (piece: Piece) => {
      const s = settingsRef.current;
      piece.released = true;
      Matter.Body.setStatic(piece.body, false);
      Matter.Sleeping.set(piece.body, false);
      const kick = clamp(s.scatter, 0, 1) * (piece.knocked ? 0.4 : 1);
      Matter.Body.setVelocity(piece.body, { x: (Math.random() - 0.5) * 6 * kick, y: -Math.random() * 2.5 * kick });
      Matter.Body.setAngularVelocity(piece.body, (Math.random() - 0.5) * 0.12 * kick);
    };

    const frame = (now: number) => {
      raf = 0;
      if (!engine || !visible) return;
      const dt = Math.min(0.05, last ? (now - last) / 1000 : 1 / 60);
      last = now;
      clock += dt;
      const s = settingsRef.current;
      engine.gravity.y = clamp(s.gravity, -3, 4) * 1.4;
      const bounce = clamp(s.bounciness, 0, 1);
      if (bounce !== lastBounciness) {
        lastBounciness = bounce;
        pieces.forEach(piece => {
          piece.body.restitution = bounce;
        });
      }
      for (const piece of pieces) if (!piece.released && (clock >= piece.at || piece.knocked)) release(piece);
      accumulator += dt * 1000;
      while (accumulator >= STEP) {
        for (const piece of pieces) {
          piece.px = piece.body.position.x;
          piece.py = piece.body.position.y;
          piece.pa = piece.body.angle;
        }
        Matter.Engine.update(engine, STEP);
        accumulator -= STEP;
      }
      draw(accumulator / STEP);
      const settled = pieces.every(piece => piece.released && (piece.body.isSleeping || piece.body.speed < 0.05));
      if (s.restoreDelay > 0 && settled && !inside && !drag) {
        quietSince ??= now;
        if (now - quietSince > s.restoreDelay * 1000) {
          restore();
          return;
        }
      } else quietSince = null;
      raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (!raf && engine && visible) {
        last = 0;
        raf = requestAnimationFrame(frame);
      }
    };

    const fall = () => {
      if (phase !== 'idle' || reduced) return;
      const elements = [...block.querySelectorAll<HTMLElement>('[data-piece]')];
      if (!elements.length) return;
      const s = settingsRef.current;
      const box = container.getBoundingClientRect();
      const originX = box.left + container.clientLeft;
      const originY = box.top + container.clientTop;
      const rects = elements.map(element => {
        const rect = element.getBoundingClientRect();
        return { x: rect.left - originX, y: rect.top - originY, w: rect.width, h: rect.height };
      });
      block.style.minHeight = `${block.offsetHeight}px`;
      const world = Matter.Engine.create({ enableSleeping: true, positionIterations: 10, velocityIterations: 8 });
      world.gravity.y = clamp(s.gravity, -3, 4) * 1.4;
      walls = [
        Matter.Bodies.rectangle(0, 0, 10000, WALL, { isStatic: true, friction: 0.8 }),
        Matter.Bodies.rectangle(0, 0, WALL, 10000, { isStatic: true, friction: 0.3 }),
        Matter.Bodies.rectangle(0, 0, WALL, 10000, { isStatic: true, friction: 0.3 }),
        Matter.Bodies.rectangle(0, 0, 10000, WALL, { isStatic: true, friction: 0.3 })
      ];
      const count = rects.length;
      const center = rects.reduce((sum, rect) => sum + rect.x + rect.w / 2, 0) / count;
      const span = Math.max(1, ...rects.map(rect => Math.abs(rect.x + rect.w / 2 - center)));
      const shuffled = rects.map((_, index) => index).sort(() => Math.random() - 0.5);
      pieces = elements.map((element, index) => {
        const rect = rects[index];
        const radius = Math.max(0, Math.min(variant === 'tiles' ? rect.h * 0.28 : 4, rect.w / 2 - 1, rect.h / 2 - 1));
        const body = Matter.Bodies.rectangle(
          rect.x + rect.w / 2,
          rect.y + rect.h / 2,
          Math.max(2, rect.w - 1),
          Math.max(2, rect.h - 1),
          {
            chamfer: radius > 0.5 ? { radius } : undefined,
            restitution: clamp(s.bounciness, 0, 1),
            friction: 0.4,
            frictionStatic: 0.8,
            frictionAir: 0.012,
            density: 0.0015,
            slop: 0.02
          }
        );
        Matter.Body.setStatic(body, true);
        const rank =
          s.order === 'random'
            ? shuffled.indexOf(index)
            : s.order === 'center'
              ? (Math.abs(rect.x + rect.w / 2 - center) / span) * (count - 1)
              : index;
        element.style.position = 'absolute';
        element.style.left = '0';
        element.style.top = '0';
        element.style.width = `${rect.w}px`;
        element.style.height = `${rect.h}px`;
        element.style.margin = '0';
        element.style.transform = `translate3d(${rect.x}px, ${rect.y}px, 0)`;
        return {
          element,
          body,
          w: rect.w,
          h: rect.h,
          x0: rect.x,
          y0: rect.y,
          px: body.position.x,
          py: body.position.y,
          pa: 0,
          dx: body.position.x,
          dy: body.position.y,
          da: 0,
          at: s.order === 'together' ? 0 : rank * Math.max(0, s.stagger),
          released: false
        };
      });
      Matter.Composite.add(world.world, [...walls, ...pieces.map(piece => piece.body)]);
      const byBody = new Map(pieces.map(piece => [piece.body, piece]));
      Matter.Events.on(world, 'collisionStart', event => {
        const down = Math.sign(world.gravity.y) || 1;
        for (const pair of event.pairs) {
          const a = byBody.get(pair.bodyA);
          const b = byBody.get(pair.bodyB);
          if (!a || !b || a.released === b.released) continue;
          const [moving, still] = a.released ? [a, b] : [b, a];
          if ((still.body.position.y - moving.body.position.y) * down > still.h * 0.25) still.knocked = true;
        }
      });
      engine = world;
      placeWalls();
      phase = 'falling';
      container.dataset.phase = 'falling';
      clock = 0;
      accumulator = 0;
      quietSince = null;
      lastBounciness = clamp(s.bounciness, 0, 1);
      wake();
    };

    const restore = () => {
      if (phase !== 'falling') return;
      phase = 'restoring';
      container.dataset.phase = 'restoring';
      if (drag && engine) {
        Matter.Composite.remove(engine.world, drag.constraint);
        drag = null;
      }
      cancelAnimationFrame(raf);
      raf = 0;
      const easing = springEase();
      const order = [...pieces].sort((a, b) => a.body.position.y - b.body.position.y);
      const animations = order.map((piece, index) => {
        const angle = Math.atan2(Math.sin(piece.body.angle), Math.cos(piece.body.angle));
        const from = `translate3d(${(piece.body.position.x - piece.w / 2).toFixed(2)}px, ${(piece.body.position.y - piece.h / 2).toFixed(2)}px, 0) rotate(${angle.toFixed(4)}rad)`;
        const to = `translate3d(${piece.x0}px, ${piece.y0}px, 0) rotate(0rad)`;
        piece.element.style.transform = to;
        return piece.element.animate([{ transform: from }, { transform: to }], {
          duration: 760,
          delay: Math.min(index * 14, 360),
          easing,
          fill: 'backwards'
        });
      });
      Promise.all(animations.map(animation => animation.finished.catch(() => null))).then(() => {
        if (phase !== 'restoring') return;
        reset();
      });
    };

    const reset = (rearm = true) => {
      cancelAnimationFrame(raf);
      raf = 0;
      if (engine) {
        Matter.Composite.clear(engine.world, false);
        Matter.Engine.clear(engine);
      }
      engine = null;
      for (const piece of pieces) {
        piece.element.getAnimations().forEach(animation => animation.cancel());
        piece.element.style.position = '';
        piece.element.style.left = '';
        piece.element.style.top = '';
        piece.element.style.width = '';
        piece.element.style.height = '';
        piece.element.style.margin = '';
        piece.element.style.transform = '';
      }
      pieces = [];
      walls = [];
      drag = null;
      block.style.minHeight = '';
      phase = 'idle';
      delete container.dataset.phase;
      delete container.dataset.dragging;
      if (rearm) armed = true;
    };

    const onEnter = () => {
      inside = true;
      if (settingsRef.current.trigger === 'hover') fall();
    };
    const onLeave = () => {
      inside = false;
    };
    const onClick = () => {
      if (settingsRef.current.trigger === 'click') fall();
    };

    const onDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      if (!engine || phase !== 'falling' || !s.draggable || (event.pointerType === 'mouse' && event.button !== 0))
        return;
      const point = local(event);
      const bodies = pieces.filter(piece => piece.released).map(piece => piece.body);
      const hit = Matter.Query.point(bodies, point)[0];
      if (!hit) return;
      event.preventDefault();
      container.setPointerCapture?.(event.pointerId);
      Matter.Sleeping.set(hit, false);
      const constraint = Matter.Constraint.create({
        pointA: point,
        bodyB: hit,
        pointB: { x: point.x - hit.position.x, y: point.y - hit.position.y },
        stiffness: clamp(s.mouseConstraintStiffness, 0.01, 1),
        damping: 0.08,
        length: 0
      });
      Matter.Composite.add(engine.world, constraint);
      drag = { constraint, id: event.pointerId };
      container.dataset.dragging = '';
      wake();
    };

    const onMove = (event: PointerEvent) => {
      const point = local(event);
      const now = performance.now();
      const dt = Math.max(1, now - pointer.time);
      if (pointer.time && dt < 120) {
        const blend = Math.min(1, dt / 40);
        pointer.vx += ((point.x - pointer.x) / dt - pointer.vx) * blend;
        pointer.vy += ((point.y - pointer.y) / dt - pointer.vy) * blend;
      } else {
        pointer.vx = 0;
        pointer.vy = 0;
      }
      pointer.x = point.x;
      pointer.y = point.y;
      pointer.time = now;
      inside = true;
      if (phase === 'idle' && settingsRef.current.trigger === 'hover') fall();
      if (phase !== 'falling') return;
      if (drag && event.pointerId === drag.id) {
        drag.constraint.pointA = point;
        return;
      }
      const s = settingsRef.current;
      const push = clamp(s.cursorPush, 0, 2);
      const speed = Math.hypot(pointer.vx, pointer.vy);
      if (!push || speed < 0.35) return;
      let touched = false;
      for (const piece of pieces) {
        if (!piece.released) continue;
        const { body } = piece;
        const reach = Math.max(piece.w, piece.h) / 2 + 18;
        const distance = Math.hypot(body.position.x - point.x, body.position.y - point.y);
        if (distance > reach) continue;
        if (now - (piece.pushed || 0) < 60) continue;
        piece.pushed = now;
        const falloff = 1 - (distance / reach) ** 2;
        const kick = Math.min(20, speed * push * falloff * 16);
        Matter.Sleeping.set(body, false);
        Matter.Body.setVelocity(body, {
          x: body.velocity.x + (pointer.vx / speed) * kick,
          y: body.velocity.y + (pointer.vy / speed) * kick - kick * 0.7
        });
        Matter.Body.setAngularVelocity(body, body.angularVelocity + (Math.random() - 0.5) * 0.06 * push);
        touched = true;
      }
      if (touched) wake();
    };

    const onUp = (event: PointerEvent) => {
      if (!drag || event.pointerId !== drag.id) return;
      if (engine) Matter.Composite.remove(engine.world, drag.constraint);
      drag = null;
      delete container.dataset.dragging;
    };

    const observer =
      typeof IntersectionObserver === 'undefined'
        ? null
        : new IntersectionObserver(
            entries => {
              const entry = entries[entries.length - 1];
              visible = entry.isIntersecting;
              if (visible) wake();
              if (settingsRef.current.trigger !== 'scroll') return;
              if (entry.intersectionRatio >= 0.3) {
                if (armed) {
                  armed = false;
                  fall();
                }
              } else if (phase === 'idle') armed = true;
            },
            { threshold: [0, 0.3] }
          );
    observer?.observe(container);

    const resizeObserver = new ResizeObserver(() => {
      if (phase === 'falling') {
        placeWalls();
        wake();
      }
    });
    resizeObserver.observe(container);

    container.addEventListener('pointerenter', onEnter);
    container.addEventListener('pointerleave', onLeave);
    container.addEventListener('click', onClick);
    container.addEventListener('pointerdown', onDown);
    container.addEventListener('pointermove', onMove);
    container.addEventListener('pointerup', onUp);
    container.addEventListener('pointercancel', onUp);

    let cancelled = false;
    if (trigger === 'auto') {
      const ready = document.fonts?.ready ?? Promise.resolve();
      ready.then(() => {
        if (!cancelled) requestAnimationFrame(() => !cancelled && fall());
      });
    }

    return () => {
      cancelled = true;
      observer?.disconnect();
      resizeObserver.disconnect();
      container.removeEventListener('pointerenter', onEnter);
      container.removeEventListener('pointerleave', onLeave);
      container.removeEventListener('click', onClick);
      container.removeEventListener('pointerdown', onDown);
      container.removeEventListener('pointermove', onMove);
      container.removeEventListener('pointerup', onUp);
      container.removeEventListener('pointercancel', onUp);
      phase = 'idle';
      reset(false);
    };
  }, [groups, split, variant, fontSize, trigger]);

  const pieceClass = `${PIECE_CLASS} ${variant === 'tiles' ? PIECE_TILE_CLASS : PIECE_TEXT_CLASS}${wireframes ? ` ${WIREFRAME_CLASS}` : ''}`;

  return (
    <div
      ref={containerRef}
      className={`${ROOT_CLASS} ${className}`.trim()}
      data-trigger={trigger}
      data-draggable={draggable ? '' : undefined}
      style={
        {
          ...(THEMES[theme] ?? THEMES.dark),
          '--falling-text-accent': accentColor,
          '--falling-text-accent-ink': readableOn(accentColor),
          background: backgroundColor,
          fontSize,
          ...style
        } as CSSProperties
      }
    >
      <div ref={textRef} className={TEXT_CLASS}>
        {groups.map((group, index) => (
          <Fragment key={index}>
            {index > 0 && ' '}
            {split === 'letters' ? (
              <span className="whitespace-nowrap">
                {[...group.word].map((letter, position) => (
                  <span
                    key={position}
                    className={`${pieceClass}${group.highlighted ? ` ${highlightClass}` : ''}`}
                    data-piece=""
                    data-highlight={group.highlighted ? '' : undefined}
                  >
                    {letter}
                  </span>
                ))}
              </span>
            ) : (
              <span
                className={`${pieceClass}${group.highlighted ? ` ${highlightClass}` : ''}`}
                data-piece=""
                data-highlight={group.highlighted ? '' : undefined}
              >
                {group.word}
              </span>
            )}
          </Fragment>
        ))}
      </div>
    </div>
  );
};

export default FallingText;

'use client';

import { useEffect, useLayoutEffect, useMemo, useRef, type CSSProperties, type ReactNode } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

type SplitBy = 'char' | 'word' | 'line';
type Hinge = 'top' | 'bottom' | 'left' | 'right';
type Trigger = 'mount' | 'hover' | 'scroll' | 'loop';
type StaggerFrom = 'start' | 'center' | 'end' | 'edges' | 'random';
type FoldStyle = 'paper' | 'blinds' | 'flip';
type Axis = 'rotateX' | 'rotateY';

export interface FoldTextProps {
  text?: string;
  splitBy?: SplitBy;
  hinge?: Hinge;
  foldStyle?: FoldStyle;
  duration?: number;
  stagger?: number;
  staggerFrom?: StaggerFrom;
  foldAngle?: number;
  ease?: string;
  perspective?: number;
  creaseShading?: number;
  trigger?: Trigger;
  loopDelay?: number;
  hoverRefold?: boolean;
  refoldRadius?: number;
  refoldAngle?: number;
  fontSize?: string | number;
  fontWeight?: string | number;
  color?: string;
  className?: string;
  style?: CSSProperties;
}

type HingeConfig = {
  origin: string;
  axis: Axis;
  sign: number;
  originClass: string;
  shadeClass: string;
};

type Piece = {
  element: HTMLElement;
  parts: HTMLElement[];
  t: number;
  f: number;
  r: number;
  aim: number;
};

type Point = { x: number; y: number };

const useIsomorphicLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;

const HINGES: Record<Hinge, HingeConfig> = {
  top: {
    origin: '50% 0%',
    axis: 'rotateX',
    sign: -1,
    originClass: 'origin-top',
    shadeClass:
      'after:bg-[linear-gradient(180deg,rgba(0,0,0,0.58)_0%,rgba(0,0,0,0.22)_42%,rgba(255,255,255,0.26)_100%)]'
  },
  bottom: {
    origin: '50% 100%',
    axis: 'rotateX',
    sign: 1,
    originClass: 'origin-bottom',
    shadeClass: 'after:bg-[linear-gradient(0deg,rgba(0,0,0,0.58)_0%,rgba(0,0,0,0.22)_42%,rgba(255,255,255,0.26)_100%)]'
  },
  left: {
    origin: '0% 50%',
    axis: 'rotateY',
    sign: 1,
    originClass: 'origin-left',
    shadeClass: 'after:bg-[linear-gradient(90deg,rgba(0,0,0,0.58)_0%,rgba(0,0,0,0.22)_42%,rgba(255,255,255,0.26)_100%)]'
  },
  right: {
    origin: '100% 50%',
    axis: 'rotateY',
    sign: -1,
    originClass: 'origin-right',
    shadeClass:
      'after:bg-[linear-gradient(270deg,rgba(0,0,0,0.58)_0%,rgba(0,0,0,0.22)_42%,rgba(255,255,255,0.26)_100%)]'
  }
};

const PIECE_CLASS = 'relative inline-block [backface-visibility:hidden] motion-reduce:[transform:none]!';

const BLINDS_CLASS = 'relative inline-block [perspective:var(--fold-perspective)]';

const SLAT_CLASS = 'inline-block [backface-visibility:hidden] motion-reduce:[transform:none]!';

const SHADE_CLASS =
  'after:pointer-events-none after:absolute after:inset-0 after:content-[attr(data-fold-text)] after:text-transparent after:[-webkit-text-fill-color:transparent] after:bg-clip-text after:opacity-[var(--fold-crease,0)] motion-reduce:after:opacity-0!';

const SLATS: Record<Axis, { origins: string[]; clips: string[] }> = {
  rotateX: {
    origins: ['50% 25%', '50% 75%'],
    clips: ['inset(-40% -20% 50% -20%)', 'inset(50% -20% -40% -20%)']
  },
  rotateY: {
    origins: ['25% 50%', '75% 50%'],
    clips: ['inset(-40% 50% -40% -20%)', 'inset(-40% -20% -40% 50%)']
  }
};

const FOLD_STYLES: FoldStyle[] = ['paper', 'blinds', 'flip'];
const SLAT_DELAY = 0.24;

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));

const FoldText = ({
  text = 'Design unfolds',
  splitBy = 'char',
  hinge = 'top',
  foldStyle = 'paper',
  duration = 0.65,
  stagger = 0.045,
  staggerFrom = 'start',
  foldAngle = 92,
  ease = 'power3.out',
  perspective = 700,
  creaseShading = 0.55,
  trigger = 'mount',
  loopDelay = 1.4,
  hoverRefold = false,
  refoldRadius = 140,
  refoldAngle = 45,
  fontSize = 80,
  fontWeight = 800,
  color = 'currentColor',
  className = '',
  style = {}
}: FoldTextProps) => {
  const rootRef = useRef<HTMLSpanElement | null>(null);
  const safeHinge: Hinge = HINGES[hinge] ? hinge : 'top';
  const hingeConfig = HINGES[safeHinge];
  const safeStyle: FoldStyle = FOLD_STYLES.includes(foldStyle) ? foldStyle : 'paper';
  const safeCrease = clamp(creaseShading, 0, 1);
  const safeAngle = clamp(foldAngle, 0, 180);
  const safeStagger = Math.max(0, stagger);
  const safeDelay = Math.max(0, loopDelay);
  const safeRadius = Math.max(1, refoldRadius);
  const safeRefold = clamp(refoldAngle, 0, 180);
  const startsFolded = trigger !== 'hover';

  const segments = useMemo<ReactNode[]>(() => {
    const { originClass, shadeClass } = HINGES[safeHinge];
    const pieceClass = `${PIECE_CLASS} ${SHADE_CLASS} ${originClass} ${shadeClass}`;
    const slatClass = `${SLAT_CLASS} ${SHADE_CLASS} ${shadeClass}`;

    const renderPiece = (content: string, key: string, isLine = false): ReactNode => (
      <span
        className={
          isLine
            ? 'block [perspective:var(--fold-perspective)]'
            : 'inline-block align-baseline [perspective:var(--fold-perspective)]'
        }
        key={key}
      >
        {safeStyle === 'blinds' ? (
          <span className={BLINDS_CLASS} data-fold-piece="" style={startsFolded ? { opacity: 0 } : undefined}>
            <span className={`relative ${slatClass}`} data-fold-text={content}>
              {content}
            </span>
            <span className={`invisible absolute inset-0 ${slatClass}`} data-fold-text={content}>
              {content}
            </span>
          </span>
        ) : (
          <span
            className={pieceClass}
            data-fold-piece=""
            data-fold-text={content}
            style={startsFolded ? { opacity: 0 } : undefined}
          >
            {content}
          </span>
        )}
      </span>
    );

    if (splitBy === 'line') {
      return text.split('\n').map((line, index) => renderPiece(line || '\u00A0', `line-${index}`, true));
    }

    return text.split(/(\s+)/).flatMap((part, partIndex): ReactNode[] => {
      if (!part) return [];

      if (/^\s+$/.test(part)) {
        return part
          .split('\n')
          .flatMap((spaces, lineIndex) => [lineIndex > 0 ? <br key={`br-${partIndex}-${lineIndex}`} /> : null, spaces])
          .filter(Boolean);
      }

      if (splitBy === 'word') return [renderPiece(part, `word-${partIndex}`)];

      return [
        <span className="inline-block whitespace-nowrap" key={`word-${partIndex}`}>
          {Array.from(part).map((char, charIndex) => renderPiece(char, `char-${partIndex}-${charIndex}`))}
        </span>
      ];
    });
  }, [text, splitBy, safeHinge, safeStyle, startsFolded]);

  useIsomorphicLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;

    const elements = Array.from(root.querySelectorAll<HTMLElement>('[data-fold-piece]'));
    if (!elements.length) return undefined;

    const reduceMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    const { axis, sign, origin } = hingeConfig;
    const slats = SLATS[axis];
    const unfoldEase = gsap.parseEase(reduceMotion ? 'power1.out' : ease) || gsap.parseEase('power3.out');
    const foldEase = gsap.parseEase(reduceMotion ? 'power1.in' : 'power2.in');
    const angle = reduceMotion ? 0 : safeStyle === 'flip' ? 180 : safeAngle;
    const crease = reduceMotion ? 0 : safeCrease;
    const refold = hoverRefold && !reduceMotion ? safeRefold : 0;
    const lift = safeStyle === 'flip' && !reduceMotion ? 0.45 : 0;
    const unfoldDuration = reduceMotion ? Math.min(duration, 0.22) : duration;
    const staggerVars: gsap.StaggerVars = {
      each: reduceMotion ? Math.min(safeStagger, 0.02) : safeStagger,
      from: staggerFrom
    };

    const pieces = elements.map((element): Piece => {
      const parts = safeStyle === 'blinds' ? (Array.from(element.children) as HTMLElement[]) : [element];
      if (safeStyle === 'blinds') {
        element.style.opacity = '1';
        parts.forEach((part, index) => {
          part.style.transformOrigin = slats.origins[index];
          if (index > 0) part.style.clipPath = slats.clips[index];
        });
      } else {
        element.style.transformOrigin = safeStyle === 'flip' ? '50% 50%' : origin;
        element.style.backfaceVisibility = safeStyle === 'flip' ? 'visible' : '';
      }
      return { element, parts, t: startsFolded ? 0 : 1, f: 0, r: 0, aim: 0 };
    });

    const shade = (progress: number, tilt: number) => String(crease * clamp(1 - progress + tilt / 90, 0, 1));

    const render = () => {
      pieces.forEach(piece => {
        const tilt = piece.r * refold;

        if (safeStyle === 'blinds') {
          let resting = tilt < 0.05;
          piece.parts.forEach((part, index) => {
            const offset = index * SLAT_DELAY;
            const open = unfoldEase(clamp((piece.t - offset) / (1 - SLAT_DELAY), 0, 1));
            const close = foldEase(clamp((piece.f - offset) / (1 - SLAT_DELAY), 0, 1));
            const progress = open * (1 - close);
            if (Math.abs(1 - progress) > 0.002) resting = false;
            part.style.transform = `${axis}(${sign * ((1 - progress) * angle + tilt)}deg)`;
            part.style.opacity = String(clamp(progress, 0, 1));
            part.style.setProperty('--fold-crease', shade(progress, tilt));
          });
          piece.parts[0].style.clipPath = resting ? 'none' : slats.clips[0];
          piece.parts[1].style.visibility = resting ? 'hidden' : 'visible';
          return;
        }

        const progress = unfoldEase(piece.t) * (1 - foldEase(piece.f));
        const rise = lift * Math.sin(Math.PI * clamp(progress, 0, 1));
        const turn = `${axis}(${sign * ((1 - progress) * angle + tilt)}deg)`;
        piece.element.style.transform = rise > 0.001 ? `translateZ(${rise}em) ${turn}` : turn;
        piece.element.style.opacity = String(clamp(progress, 0, 1));
        piece.element.style.setProperty('--fold-crease', shade(progress, tilt));
      });
    };

    let timeline: gsap.core.Timeline | null = null;
    let scrollTrigger: ScrollTrigger | null = null;

    const play = (loop: boolean) => {
      timeline?.kill();
      timeline = gsap.timeline({ onUpdate: render, ...(loop ? { repeat: -1, repeatDelay: 0.35 } : {}) });
      timeline.fromTo(pieces, { t: 0, f: 0 }, { t: 1, duration: unfoldDuration, ease: 'none', stagger: staggerVars });
      if (loop) {
        timeline.to(
          pieces,
          { f: 1, duration: unfoldDuration * 0.75, ease: 'none', stagger: staggerVars },
          `+=${safeDelay}`
        );
      }
      render();
    };

    const handleEnter = () => play(false);

    if (trigger === 'hover') {
      render();
      root.addEventListener('mouseenter', handleEnter);
    } else if (trigger === 'scroll') {
      render();
      scrollTrigger = ScrollTrigger.create({
        trigger: root,
        start: 'top 82%',
        once: true,
        onEnter: handleEnter
      });
    } else {
      play(trigger === 'loop');
    }

    let pointer: Point | null = null;
    let centers: Point[] | null = null;
    let measured: { width: number; height: number } | null = null;
    let relaxing = false;

    const measure = (box: DOMRect) => {
      centers = pieces.map(piece => {
        const rect = (piece.element.parentElement ?? piece.element).getBoundingClientRect();
        return { x: rect.left - box.left + rect.width / 2, y: rect.top - box.top + rect.height / 2 };
      });
      measured = { width: box.width, height: box.height };
    };

    const relax = (time: number, deltaTime: number) => {
      const step = Math.min(deltaTime, 64) / 1000;
      let moving = false;
      pieces.forEach(piece => {
        const rate = piece.aim > piece.r ? 14 : 6;
        piece.r += (piece.aim - piece.r) * (1 - Math.exp(-rate * step));
        if (Math.abs(piece.aim - piece.r) > 0.001) moving = true;
        else piece.r = piece.aim;
      });
      render();
      if (!moving) {
        gsap.ticker.remove(relax);
        relaxing = false;
      }
    };

    const aim = () => {
      const box = root.getBoundingClientRect();
      const near =
        pointer &&
        pointer.x > box.left - safeRadius &&
        pointer.x < box.right + safeRadius &&
        pointer.y > box.top - safeRadius &&
        pointer.y < box.bottom + safeRadius;
      if (
        near &&
        (!centers || !measured || Math.abs(box.width - measured.width) + Math.abs(box.height - measured.height) > 1)
      ) {
        measure(box);
      }
      let changed = false;
      pieces.forEach((piece, index) => {
        let value = 0;
        if (near && pointer && centers) {
          const center = centers[index];
          const distance = Math.hypot(box.left + center.x - pointer.x, box.top + center.y - pointer.y) / safeRadius;
          if (distance < 1) value = 1 - distance * distance * (3 - 2 * distance);
        }
        if (value !== piece.aim) changed = true;
        piece.aim = value;
      });
      if (changed && !relaxing) {
        relaxing = true;
        gsap.ticker.add(relax);
      }
    };

    const handleMove = (event: PointerEvent) => {
      pointer = { x: event.clientX, y: event.clientY };
      aim();
    };

    const handleLeave = () => {
      pointer = null;
      aim();
    };

    const handleScroll = () => {
      if (pointer) aim();
    };

    if (refold) {
      window.addEventListener('pointermove', handleMove, { passive: true });
      window.addEventListener('scroll', handleScroll, { passive: true, capture: true });
      document.documentElement.addEventListener('pointerleave', handleLeave);
    }

    return () => {
      root.removeEventListener('mouseenter', handleEnter);
      window.removeEventListener('pointermove', handleMove);
      window.removeEventListener('scroll', handleScroll, { capture: true });
      document.documentElement.removeEventListener('pointerleave', handleLeave);
      gsap.ticker.remove(relax);
      scrollTrigger?.kill();
      timeline?.kill();
      gsap.killTweensOf(pieces);
    };
  }, [
    segments,
    hingeConfig,
    safeStyle,
    duration,
    safeStagger,
    staggerFrom,
    safeAngle,
    ease,
    safeCrease,
    trigger,
    safeDelay,
    hoverRefold,
    safeRadius,
    safeRefold,
    startsFolded
  ]);

  const rootStyle = {
    color,
    fontSize: typeof fontSize === 'number' ? `${fontSize}px` : fontSize,
    fontWeight,
    '--fold-perspective': `${Math.max(120, perspective)}px`,
    ...style
  } as CSSProperties;

  return (
    <span
      ref={rootRef}
      className={`inline-block whitespace-pre-wrap select-text leading-[0.95] tracking-[-0.04em] ${className}`.trim()}
      style={rootStyle}
    >
      <span className="sr-only select-none">{text}</span>
      <span aria-hidden="true">{segments}</span>
    </span>
  );
};

export default FoldText;

'use client';

import React, { useEffect, useRef } from 'react';

const INTRO_PEAK = 2;
const BURST_ATTACK = 70;
const BURST_DECAY = 240;

type FuzzDirection = 'horizontal' | 'vertical' | 'both';
type FuzzTrigger = 'hover' | 'always' | 'click';
type Rgb = [number, number, number];

interface FuzzyTextProps {
  children: React.ReactNode;
  fontSize?: number | string;
  fontWeight?: string | number;
  fontFamily?: string;
  color?: string;
  enableHover?: boolean;
  baseIntensity?: number;
  hoverIntensity?: number;
  fuzzRange?: number;
  fps?: number;
  direction?: FuzzDirection;
  transitionDuration?: number;
  clickEffect?: boolean;
  glitchMode?: boolean;
  glitchInterval?: number;
  glitchDuration?: number;
  gradient?: string[] | null;
  letterSpacing?: number;
  sliceSize?: number;
  trigger?: FuzzTrigger;
  intro?: boolean;
  introDuration?: number;
  colorSplit?: number;
  className?: string;
}

interface Tuning {
  enableHover: boolean;
  baseIntensity: number;
  hoverIntensity: number;
  fps: number;
  transitionDuration: number;
  clickEffect: boolean;
  sliceSize: number;
  trigger: FuzzTrigger;
  intro: boolean;
  introDuration: number;
  colorSplit: number;
}

interface ChannelLayer {
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D | null;
}

const followsText = (value?: string) => !value || /^(currentcolor|inherit)$/i.test(value);

let colorProbe: CanvasRenderingContext2D | null = null;

const toRgb = (value: string): Rgb => {
  if (!colorProbe) {
    const probe = document.createElement('canvas');
    probe.width = 1;
    probe.height = 1;
    colorProbe = probe.getContext('2d', { willReadFrequently: true });
  }
  if (!colorProbe) return [255, 255, 255];
  colorProbe.clearRect(0, 0, 1, 1);
  colorProbe.fillStyle = '#000';
  colorProbe.fillStyle = value;
  colorProbe.fillRect(0, 0, 1, 1);
  const [r, g, b] = colorProbe.getImageData(0, 0, 1, 1).data;
  return [r, g, b];
};

const channelColor = (rgb: Rgb, channel: number, additive: boolean) =>
  `rgb(${rgb.map((value, index) => (index === channel ? value : additive ? 0 : 255)).join(',')})`;

const FuzzyText: React.FC<FuzzyTextProps> = ({
  children,
  fontSize = 'clamp(2rem, 8vw, 8rem)',
  fontWeight = 900,
  fontFamily = 'inherit',
  color = 'currentColor',
  enableHover = true,
  baseIntensity = 0.18,
  hoverIntensity = 0.5,
  fuzzRange = 30,
  fps = 60,
  direction = 'horizontal',
  transitionDuration = 0,
  clickEffect = false,
  glitchMode = false,
  glitchInterval = 2000,
  glitchDuration = 200,
  gradient = null,
  letterSpacing = 0,
  sliceSize = 1,
  trigger = 'hover',
  intro = false,
  introDuration = 1400,
  colorSplit = 0,
  className = ''
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const glitchRef = useRef(false);
  const introRef = useRef({ start: 0, done: !intro });
  const tuningRef = useRef<Tuning>({
    enableHover,
    baseIntensity,
    hoverIntensity,
    fps,
    transitionDuration,
    clickEffect,
    sliceSize,
    trigger,
    intro,
    introDuration,
    colorSplit
  });
  const text = React.Children.toArray(children).join('');
  const gradientKey = Array.isArray(gradient) && gradient.length >= 2 ? gradient.join('|') : '';
  const splitOn = colorSplit > 0;

  useEffect(() => {
    tuningRef.current = {
      enableHover,
      baseIntensity,
      hoverIntensity,
      fps,
      transitionDuration,
      clickEffect,
      sliceSize,
      trigger,
      intro,
      introDuration,
      colorSplit
    };
  }, [
    enableHover,
    baseIntensity,
    hoverIntensity,
    fps,
    transitionDuration,
    clickEffect,
    sliceSize,
    trigger,
    intro,
    introDuration,
    colorSplit
  ]);

  useEffect(() => {
    if (!glitchMode || window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
    let startTimer: ReturnType<typeof setTimeout>;
    let endTimer: ReturnType<typeof setTimeout>;
    const schedule = () => {
      startTimer = setTimeout(() => {
        glitchRef.current = true;
        endTimer = setTimeout(() => {
          glitchRef.current = false;
          schedule();
        }, glitchDuration);
      }, glitchInterval);
    };
    schedule();
    return () => {
      clearTimeout(startTimer);
      clearTimeout(endTimer);
      glitchRef.current = false;
    };
  }, [glitchMode, glitchInterval, glitchDuration]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    const source = document.createElement('canvas');
    const sourceCtx = source.getContext('2d');
    const scratch = document.createElement('canvas');
    const scratchCtx = scratch.getContext('2d');
    const channels: ChannelLayer[] = splitOn
      ? [0, 1, 2].map(() => {
          const layer = document.createElement('canvas');
          return { canvas: layer, ctx: layer.getContext('2d') };
        })
      : [];
    if (!canvas || !ctx || !sourceCtx || !scratchCtx || channels.some(channel => !channel.ctx)) return;
    const layers = channels as { canvas: HTMLCanvasElement; ctx: CanvasRenderingContext2D }[];

    const reduceMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const usesInk = followsText(color) && !gradientKey;
    const splitPad = splitOn ? Math.ceil(fuzzRange * 0.5) + 4 : 0;
    const padX = fuzzRange + 20 + (direction === 'vertical' ? 0 : splitPad);
    const padY = direction === 'horizontal' ? 0 : fuzzRange + 10 + (direction === 'vertical' ? splitPad : 0);
    const inset = 5;
    let cancelled = false;
    let built = false;
    let visible = true;
    let frame = 0;
    let resizeFrame = 0;
    let lastFrame = 0;
    let lastInkCheck = 0;
    let clickTimer: ReturnType<typeof setTimeout> | undefined;
    let hovering = false;
    let clicking = false;
    let burstAt = 0;
    let eased = reduceMotion ? 0 : tuningRef.current.baseIntensity;
    let intensity = eased;
    let coarse = 1;
    let drawn = -1;
    let ink = '';
    let blend: GlobalCompositeOperation = 'lighter';
    let dpr = 1;
    let fontPx = 16;
    let rows = new Int32Array(1);
    let cols = new Int32Array(1);
    let box = { left: 0, ascent: 0, width: 0, height: 0, cssWidth: 0, cssHeight: 0 };

    const family = () => (fontFamily === 'inherit' ? getComputedStyle(canvas).fontFamily || 'sans-serif' : fontFamily);
    const font = () => `${fontWeight} ${fontPx}px ${family()}`;
    const resolveInk = () => (usesInk ? getComputedStyle(canvas).color || '#000' : color);
    const pixelRatio = () => Math.min(window.devicePixelRatio || 1, 2);
    const introPending = () => !introRef.current.done && tuningRef.current.intro && !reduceMotion;

    const measureFontSize = () => {
      if (typeof fontSize === 'number') return fontSize;
      const probe = document.createElement('span');
      probe.style.fontSize = fontSize;
      (canvas.parentElement || document.body).appendChild(probe);
      const size = parseFloat(getComputedStyle(probe).fontSize);
      probe.remove();
      return Number.isFinite(size) && size > 0 ? size : 16;
    };

    const paintText = (
      target: HTMLCanvasElement,
      targetCtx: CanvasRenderingContext2D,
      tone: (value: string) => string
    ) => {
      target.width = source.width;
      target.height = source.height;
      targetCtx.setTransform(1, 0, 0, 1, 0, 0);
      targetCtx.clearRect(0, 0, target.width, target.height);
      targetCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
      targetCtx.font = font();
      targetCtx.textBaseline = 'alphabetic';
      if (gradientKey) {
        const stops = gradientKey.split('|');
        const fill = targetCtx.createLinearGradient(0, 0, box.width + inset * 2, 0);
        stops.forEach((stop, index) => fill.addColorStop(index / (stops.length - 1), tone(stop)));
        targetCtx.fillStyle = fill;
      } else {
        targetCtx.fillStyle = tone(ink);
      }
      if (letterSpacing !== 0) {
        let x = inset;
        for (const char of text) {
          targetCtx.fillText(char, x, box.ascent);
          x += targetCtx.measureText(char).width + letterSpacing;
        }
      } else {
        targetCtx.fillText(text, inset + box.left, box.ascent);
      }
    };

    const paintSource = () => {
      paintText(source, sourceCtx, value => value);
      if (!splitOn) return;
      const tones = (gradientKey ? gradientKey.split('|') : [ink]).map(toRgb);
      const light =
        tones.reduce((sum, [r, g, b]) => sum + (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255, 0) / tones.length >= 0.5;
      blend = light ? 'lighter' : 'multiply';
      layers.forEach((channel, index) =>
        paintText(channel.canvas, channel.ctx, value => channelColor(toRgb(value), index, light))
      );
    };

    const fuzz = (image: HTMLCanvasElement, shift: number, jitter: number, step: number, amp: number) => {
      const sw = image.width;
      const sh = image.height;
      const ox = Math.round(padX * dpr);
      const oy = Math.round(padY * dpr);
      const sx = direction === 'vertical' ? 0 : shift;
      const sy = direction === 'vertical' ? shift : 0;
      const wobble = () => (jitter ? Math.round((Math.random() - 0.5) * jitter) : 0);
      if (amp < 0.5) {
        ctx.drawImage(image, ox + sx, oy + sy);
        return;
      }
      if (direction === 'vertical') {
        for (let x = 0, index = 0; x < sw; x += step, index++) {
          const w = Math.min(step, sw - x);
          ctx.drawImage(image, x, 0, w, sh, ox + x, oy + cols[index] + wobble() + sy, w, sh);
        }
        return;
      }
      const both = direction === 'both';
      const target = both ? scratchCtx : ctx;
      if (both) scratchCtx.clearRect(0, 0, scratch.width, scratch.height);
      for (let y = 0, index = 0; y < sh; y += step, index++) {
        const h = Math.min(step, sh - y);
        target.drawImage(image, 0, y, sw, h, ox + rows[index] + wobble() + sx, both ? y : oy + y, sw, h);
      }
      if (!both) return;
      const reach = Math.ceil(amp / 2 + Math.abs(sx) + jitter / 2) + 1;
      const from = Math.max(0, Math.floor((ox - reach) / step) * step);
      const to = Math.min(scratch.width, ox + sw + reach);
      for (let x = from; x < to; x += step) {
        const w = Math.min(step, to - x);
        ctx.drawImage(scratch, x, 0, w, sh, x, oy + cols[x / step], w, sh);
      }
    };

    const draw = () => {
      const tuning = tuningRef.current;
      const step = Math.max(1, Math.round(Math.max(1, tuning.sliceSize) * coarse * dpr));
      const amp = intensity * fuzzRange * dpr;
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.globalCompositeOperation = 'source-over';
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawn = intensity;
      if (amp >= 0.5) {
        if (direction === 'vertical') {
          for (let index = 0; index * step < source.width; index++) {
            cols[index] = Math.round((Math.random() - 0.5) * amp);
          }
        } else {
          for (let index = 0; index * step < source.height; index++) {
            rows[index] = Math.round((Math.random() - 0.5) * amp);
          }
          if (direction === 'both') {
            for (let index = 0; index * step < canvas.width; index++) {
              cols[index] = Math.round((Math.random() - 0.5) * amp * 0.5);
            }
          }
        }
      }
      const split = splitOn ? Math.round(tuning.colorSplit * (2 + intensity * fuzzRange * 0.18) * dpr) : 0;
      if (split < 1) {
        fuzz(source, 0, 0, step, amp);
        return;
      }
      const jitter = tuning.colorSplit * amp * 0.2;
      ctx.globalCompositeOperation = blend;
      fuzz(layers[0].canvas, -split, jitter, step, amp);
      fuzz(layers[1].canvas, 0, 0, step, amp);
      fuzz(layers[2].canvas, split, jitter, step, amp);
      ctx.globalCompositeOperation = 'source-over';
    };

    const build = () => {
      dpr = pixelRatio();
      fontPx = measureFontSize();
      sourceCtx.setTransform(1, 0, 0, 1, 0, 0);
      sourceCtx.font = font();
      const metrics = sourceCtx.measureText(text);
      const left = metrics.actualBoundingBoxLeft ?? 0;
      let width = left + (metrics.actualBoundingBoxRight ?? metrics.width);
      if (letterSpacing !== 0) {
        width = -letterSpacing;
        for (const char of text) width += sourceCtx.measureText(char).width + letterSpacing;
      }
      const ascent = metrics.actualBoundingBoxAscent ?? fontPx;
      const descent = metrics.actualBoundingBoxDescent ?? fontPx * 0.2;
      const textWidth = Math.max(1, Math.ceil(width));
      const textHeight = Math.max(1, Math.ceil(ascent + descent));
      box = {
        left,
        ascent,
        width: textWidth,
        height: textHeight,
        cssWidth: textWidth + inset * 2 + padX * 2,
        cssHeight: textHeight + padY * 2
      };
      source.width = Math.ceil((textWidth + inset * 2) * dpr);
      source.height = Math.ceil(textHeight * dpr);
      canvas.width = Math.ceil(box.cssWidth * dpr);
      canvas.height = Math.ceil(box.cssHeight * dpr);
      scratch.width = canvas.width;
      scratch.height = source.height;
      rows = new Int32Array(source.height + 1);
      cols = new Int32Array(canvas.width + 1);
      canvas.style.width = `${box.cssWidth}px`;
      canvas.style.height = `${box.cssHeight}px`;
      if (introPending() && !introRef.current.start) canvas.style.opacity = '0';
      ink = resolveInk();
      paintSource();
      built = true;
      draw();
    };

    const tick = (now: number) => {
      frame = 0;
      if (cancelled || !visible) return;
      frame = requestAnimationFrame(tick);
      const tuning = tuningRef.current;
      const interval = 1000 / Math.max(1, tuning.fps);
      if (now - lastFrame < interval - 1) return;
      lastFrame = Math.max(lastFrame + interval, now - interval);
      if (usesInk && now - lastInkCheck > 250) {
        lastInkCheck = now;
        const next = resolveInk();
        if (next !== ink) {
          ink = next;
          paintSource();
          drawn = -1;
        }
      }
      const base = reduceMotion ? 0 : tuning.baseIntensity;
      const active =
        tuning.trigger === 'always'
          ? reduceMotion
            ? base
            : tuning.hoverIntensity
          : tuning.trigger !== 'click' && hovering && tuning.enableHover
            ? tuning.hoverIntensity
            : base;
      const goal = clicking || glitchRef.current ? 1 : active;
      if (tuning.transitionDuration > 0) {
        eased += (goal - eased) * (1 - Math.pow(0.05, 1 / tuning.transitionDuration));
        if (Math.abs(goal - eased) < 0.002) eased = goal;
      } else {
        eased = goal;
      }
      let level = eased;
      let energy = 0;
      if (burstAt) {
        const age = now - burstAt;
        const envelope =
          age < BURST_ATTACK ? 1 - Math.pow(1 - age / BURST_ATTACK, 2) : Math.exp(-(age - BURST_ATTACK) / BURST_DECAY);
        if (age >= BURST_ATTACK && envelope < 0.004) {
          burstAt = 0;
        } else {
          const peak = Math.min(2, 0.6 + tuning.hoverIntensity * 1.4);
          level += (Math.max(peak, level) - level) * envelope;
          energy = envelope;
        }
      }
      const introState = introRef.current;
      if (!introState.done) {
        if (!tuning.intro || reduceMotion) {
          introState.done = true;
          canvas.style.opacity = '';
        } else {
          if (!introState.start) introState.start = now;
          const progress = Math.min(1, (now - introState.start) / Math.max(1, tuning.introDuration));
          const envelope = Math.pow(1 - progress, 2.5);
          level += (INTRO_PEAK - level) * envelope;
          energy = Math.max(energy, envelope);
          canvas.style.opacity = progress < 0.3 ? (1 - Math.pow(1 - progress / 0.3, 2)).toFixed(3) : '';
          if (progress >= 1) introState.done = true;
        }
      }
      intensity = level;
      coarse = 1 + 3 * energy * energy;
      if (intensity === 0 && drawn === 0) return;
      draw();
    };

    const observer =
      typeof IntersectionObserver !== 'undefined'
        ? new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting;
            if (visible && built && !frame && !cancelled) frame = requestAnimationFrame(tick);
          })
        : null;
    observer?.observe(canvas);

    const isOverText = (event: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      if (!built || !rect.width || !rect.height) return false;
      const x = ((event.clientX - rect.left) * box.cssWidth) / rect.width;
      const y = ((event.clientY - rect.top) * box.cssHeight) / rect.height;
      const left = padX + inset;
      return x >= left && x <= left + box.width && y >= padY && y <= padY + box.height;
    };

    const handlePointerMove = (event: PointerEvent) => {
      hovering = isOverText(event);
    };

    const handlePointerUp = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') hovering = false;
    };

    const handlePointerLeave = () => {
      hovering = false;
    };

    const handleClick = () => {
      const tuning = tuningRef.current;
      if (tuning.trigger === 'click') {
        burstAt = performance.now();
        return;
      }
      if (!tuning.clickEffect) return;
      clicking = true;
      clearTimeout(clickTimer);
      clickTimer = setTimeout(() => {
        clicking = false;
      }, 150);
    };

    const handleResize = () => {
      cancelAnimationFrame(resizeFrame);
      resizeFrame = requestAnimationFrame(() => {
        if (built && (measureFontSize() !== fontPx || pixelRatio() !== dpr)) build();
      });
    };

    canvas.addEventListener('pointermove', handlePointerMove);
    canvas.addEventListener('pointerdown', handlePointerMove);
    canvas.addEventListener('pointerup', handlePointerUp);
    canvas.addEventListener('pointerleave', handlePointerLeave);
    canvas.addEventListener('pointercancel', handlePointerLeave);
    canvas.addEventListener('click', handleClick);
    window.addEventListener('resize', handleResize);

    const start = async () => {
      fontPx = measureFontSize();
      try {
        await document.fonts?.load(font());
      } catch {
        await document.fonts?.ready;
      }
      if (cancelled) return;
      build();
      if (visible && !frame) frame = requestAnimationFrame(tick);
    };

    start();

    return () => {
      cancelled = true;
      cancelAnimationFrame(frame);
      cancelAnimationFrame(resizeFrame);
      clearTimeout(clickTimer);
      observer?.disconnect();
      canvas.removeEventListener('pointermove', handlePointerMove);
      canvas.removeEventListener('pointerdown', handlePointerMove);
      canvas.removeEventListener('pointerup', handlePointerUp);
      canvas.removeEventListener('pointerleave', handlePointerLeave);
      canvas.removeEventListener('pointercancel', handlePointerLeave);
      canvas.removeEventListener('click', handleClick);
      window.removeEventListener('resize', handleResize);
    };
  }, [text, fontSize, fontWeight, fontFamily, color, gradientKey, letterSpacing, fuzzRange, direction, splitOn]);

  return (
    <canvas
      ref={canvasRef}
      className={`${trigger === 'click' ? 'cursor-pointer' : ''} ${className}`.trim()}
      role="img"
      aria-label={text}
    />
  );
};

