import { useEffect, useRef, type CSSProperties, type FC } from 'react';

export type GlitchMode = 'slices' | 'rgb' | 'scan' | 'noise';
export type GlitchTrigger = 'always' | 'hover' | 'click';

interface GlitchTextProps {
  children: string;
  speed?: number;
  enableShadows?: boolean;
  enableOnHover?: boolean;
  offset?: number;
  shadowColors?: [string, string];
  className?: string;
  mode?: GlitchMode;
  intensity?: number;
  skew?: number;
  flicker?: boolean;
  trigger?: GlitchTrigger;
  burstDuration?: number;
  color?: string;
  fontSize?: number | string;
  fontWeight?: number | string;
}

interface GlitchSettings {
  speed: number;
  offset: number;
  intensity: number;
  skew: number;
  flicker: boolean;
  enableShadows: boolean;
  shadowColors: [string, string];
  burstDuration: number;
}

interface GlitchEvent {
  until: number;
  aTop: number;
  aHeight: number;
  bTop: number;
  bHeight: number;
  ax: number;
  bx: number;
  ay: number;
  by: number;
  skew: number;
  fresh: boolean;
}

type GlitchStyle = CSSProperties & Record<`--${string}`, string | number | undefined>;

const MODES: GlitchMode[] = ['slices', 'rgb', 'scan', 'noise'];
const GLYPHS = '#%&@$?<>/\\=+*~^!';
const SLICE_STOPS: [number, number][] = [
  [20, 50],
  [10, 60],
  [15, 55],
  [25, 35],
  [30, 40],
  [40, 20],
  [10, 60],
  [15, 55],
  [25, 35],
  [30, 40],
  [20, 50],
  [10, 60],
  [15, 55],
  [25, 35],
  [30, 40],
  [40, 20],
  [20, 50],
  [10, 60],
  [15, 55],
  [25, 35],
  [30, 40]
];

const ROOT_CLASS =
  'relative mx-auto cursor-pointer select-none whitespace-nowrap text-[clamp(2rem,10vw,8rem)] font-black';
const TEXT_CLASS = 'block origin-[0_50%] [opacity:var(--glitch-alpha,1)] [transform:skewX(var(--glitch-skew,0deg))]';
const TEXT_LAYER = {
  band: '[-webkit-mask-composite:source-in] [-webkit-mask-image:var(--glitch-mask-a),var(--glitch-mask-b)] [mask-composite:intersect] [mask-image:var(--glitch-mask-a),var(--glitch-mask-b)]',
  split: 'relative z-[1]',
  hidden:
    '[-webkit-mask-composite:source-in] [-webkit-mask-image:var(--glitch-mask-a),var(--glitch-mask-b)] [mask-composite:intersect] [mask-image:var(--glitch-mask-a),var(--glitch-mask-b)]'
};
const SLICE_CLASS = 'pointer-events-none absolute top-0 left-0 overflow-hidden origin-[0_50%]';
const SLICE_A = {
  band: '[clip-path:inset(var(--glitch-a-top,0%)_0_var(--glitch-a-bottom,100%)_0)] [opacity:var(--glitch-alpha,1)] [text-shadow:var(--glitch-a-shadow,none)] [transform:translate3d(var(--glitch-a-x,0px),var(--glitch-a-y,0px),0)_skewX(var(--glitch-skew,0deg))]',
  split:
    '[color:var(--glitch-color-a,currentColor)] [opacity:calc(var(--glitch-alpha,1)*var(--glitch-split,0))] [transform:translate3d(var(--glitch-a-x,0px),var(--glitch-a-y,0px),0)_skewX(var(--glitch-skew,0deg))]',
  hidden: 'hidden'
};
const SLICE_B = {
  band: '[-webkit-mask-image:var(--glitch-mask-a)] [clip-path:inset(var(--glitch-b-top,0%)_0_var(--glitch-b-bottom,100%)_0)] [mask-image:var(--glitch-mask-a)] [opacity:var(--glitch-alpha,1)] [text-shadow:var(--glitch-b-shadow,none)] [transform:translate3d(var(--glitch-b-x,0px),var(--glitch-b-y,0px),0)_skewX(var(--glitch-skew,0deg))]',
  split:
    '[color:var(--glitch-color-b,currentColor)] [opacity:calc(var(--glitch-alpha,1)*var(--glitch-split,0))] [transform:translate3d(var(--glitch-b-x,0px),var(--glitch-b-y,0px),0)_skewX(var(--glitch-skew,0deg))]',
  hidden: 'hidden'
};
const CHAR_CLASS =
  'relative data-[glyph]:invisible after:visible after:absolute after:top-0 after:right-0 after:left-0 after:overflow-hidden after:text-center after:content-[attr(data-glyph)] after:[color:var(--glitch-glyph,currentColor)]';

const bandMask = (band: 'a' | 'b') =>
  `linear-gradient(#000 var(--glitch-${band}-top, 0%), transparent var(--glitch-${band}-top, 0%), transparent calc(100% - var(--glitch-${band}-bottom, 100%)), #000 calc(100% - var(--glitch-${band}-bottom, 100%)))`;

const clamp = (v: number, min: number, max: number) => Math.min(max, Math.max(min, v));

const bandAt = (u: number): [number, number] => {
  const x = clamp(u, 0, 1) * (SLICE_STOPS.length - 1);
  const i = Math.min(SLICE_STOPS.length - 2, Math.floor(x));
  const f = x - i;
  const [t0, b0] = SLICE_STOPS[i];
  const [t1, b1] = SLICE_STOPS[i + 1];
  return [t0 + (t1 - t0) * f, b0 + (b1 - b0) * f];
};

const pingPong = (time: number, period: number) => {
  const p = (time / period) % 2;
  return p < 1 ? 1 - p : p - 1;
};

const fitBand = (top: number, bottom: number): [number, number] => {
  const t = clamp(top, 0, 100);
  const b = clamp(bottom, 0, 100);
  return t + b >= 100 ? [0, 100] : [t, b];
};

const makeEvent = (now: number, ms: number): GlitchEvent => {
  const r = Math.random;
  const sign = () => (r() < 0.5 ? -1 : 1);
  return {
    until: now + ms * (1 + Math.floor(r() * 3)),
    aTop: r() * 80,
    aHeight: 5 + r() * 22,
    bTop: r() * 85,
    bHeight: 3 + r() * 14,
    ax: sign() * (1.3 + r() * 1.5),
    bx: sign() * (1.1 + r() * 1.2),
    ay: (r() - 0.5) * 0.5,
    by: (r() - 0.5) * 0.5,
    skew: sign() * (0.4 + r() * 0.6),
    fresh: true
  };
};

const stepLength = (speed: number) => 70 * Math.sqrt(Math.max(0.05, speed) / 0.5);

const GlitchText: FC<GlitchTextProps> = ({
  children,
  speed = 0.5,
  enableShadows = true,
  enableOnHover = false,
  offset = 10,
  shadowColors = ['#ff0000', '#00ffff'],
  className = '',
  mode = 'slices',
  intensity = 0.5,
  skew = 0,
  flicker = false,
  trigger = 'always',
  burstDuration = 0.6,
  color,
  fontSize,
  fontWeight
}) => {
  const rootRef = useRef<HTMLDivElement>(null);
  const charRefs = useRef<Array<HTMLSpanElement | null>>([]);
  const settings: GlitchSettings = {
    speed,
    offset,
    intensity,
    skew,
    flicker,
    enableShadows,
    shadowColors,
    burstDuration
  };
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  const safeMode: GlitchMode = MODES.includes(mode) ? mode : 'slices';
  const activeTrigger: GlitchTrigger =
    trigger === 'hover' || trigger === 'click' ? trigger : enableOnHover ? 'hover' : 'always';
  const chars = safeMode === 'noise' && typeof children === 'string' ? Array.from(children) : null;
  const charCount = chars ? chars.length : 0;

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;

    const reduce = Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches);
    const cells = charRefs.current.slice(0, charCount).filter((cell): cell is HTMLSpanElement => Boolean(cell));
    const written: Record<string, string> = {};
    const swaps = new Map<number, number>();
    let raf = 0;
    let last = 0;
    let clock = 0;
    let visible = true;
    let hovering = false;
    let burstStart = 0;
    let burstEnd = 0;
    let nextStep = 0;
    let event: GlitchEvent | null = null;
    let alpha = 1;
    let jitter = [1, 1, 0, 0];

    const write = (name: string, value: string) => {
      if (written[name] === value) return;
      written[name] = value;
      root.style.setProperty(name, value);
    };

    const rest = () => {
      write('--glitch-a-top', '0%');
      write('--glitch-a-bottom', '100%');
      write('--glitch-b-top', '0%');
      write('--glitch-b-bottom', '100%');
      write('--glitch-a-x', '0px');
      write('--glitch-a-y', '0px');
      write('--glitch-b-x', '0px');
      write('--glitch-b-y', '0px');
      write('--glitch-a-shadow', 'none');
      write('--glitch-b-shadow', 'none');
      write('--glitch-skew', '0deg');
      write('--glitch-alpha', '1');
      write('--glitch-split', '0');
      swaps.forEach((_, i) => cells[i].removeAttribute('data-glyph'));
      swaps.clear();
      event = null;
    };

    const isActive = (now: number) =>
      !reduce && visible && (activeTrigger === 'always' || (activeTrigger === 'hover' && hovering) || now < burstEnd);

    const swap = (i: number, now: number, ms: number, s: GlitchSettings) => {
      const cell = cells[i];
      if (!cell || cell.textContent === ' ') return;
      cell.setAttribute('data-glyph', GLYPHS[Math.floor(Math.random() * GLYPHS.length)]);
      cell.style.setProperty('--glitch-glyph', s.enableShadows ? s.shadowColors[i % 2] : 'currentColor');
      swaps.set(i, now + ms * (1 + Math.floor(Math.random() * 3)));
    };

    const step = (now: number, s: GlitchSettings, power: number) => {
      const ms = stepLength(s.speed);
      if (event && now >= event.until) event = null;
      if (!event && Math.random() < power * power * 0.35) event = makeEvent(now, ms);
      jitter = [0.6 + Math.random() * 0.8, 0.6 + Math.random() * 0.8, Math.random() * 2 - 1, Math.random() * 2 - 1];
      alpha = s.flicker && Math.random() < 0.04 + 0.16 * power ? 0.45 + Math.random() * 0.35 : 1;

      if (cells.length) {
        swaps.forEach((until, i) => {
          if (now < until) return;
          cells[i].removeAttribute('data-glyph');
          swaps.delete(i);
        });
        const chance = 0.01 + 0.16 * power * power;
        cells.forEach((_, i) => {
          if (Math.random() < (swaps.has(i) ? 0.35 : chance)) swap(i, now, ms, s);
        });
        if (event?.fresh) {
          const start = Math.floor(Math.random() * cells.length);
          const run = 2 + Math.floor(Math.random() * 3);
          for (let k = 0; k < run; k++) swap((start + k) % cells.length, now, ms, s);
        }
      }
      if (event) event.fresh = false;
      nextStep = now + ms * (0.7 + Math.random() * 0.6);
    };

    const frame = (now: number) => {
      raf = 0;
      if (!isActive(now)) {
        rest();
        last = 0;
        return;
      }

      const s = settingsRef.current;
      const dt = last ? Math.min(0.1, (now - last) / 1000) : 0;
      last = now;
      clock += dt;

      const bursting = now < burstEnd;
      const burstLeft = bursting ? 1 - ((now - burstStart) / Math.max(1, burstEnd - burstStart)) * 0.55 : 0;
      const power = Math.max(clamp(s.intensity, 0, 1), burstLeft);
      if (now >= nextStep) step(now, s, power);

      const live = event && now < event.until ? event : null;
      const scale = 0.4 + 1.2 * power;
      const off = Math.max(0, s.offset);
      const pace = Math.max(0.05, s.speed);
      let a: [number, number] = [0, 100];
      let b: [number, number] = [0, 100];
      let ax = 0;
      let ay = 0;
      let bx = 0;
      let by = 0;
      let split = 0;

      if (safeMode === 'slices') {
        a = bandAt(pingPong(clock, 3 * pace));
        b = bandAt(pingPong(clock, 2 * pace));
        ax = off * scale;
        bx = -off * scale;
        if (live) {
          a = [live.aTop, 100 - live.aTop - live.aHeight];
          b = [live.bTop, 100 - live.bTop - live.bHeight];
          ax = off * scale * live.ax;
          bx = off * scale * live.bx;
          ay = off * live.ay;
          by = off * live.by;
        }
      } else if (safeMode === 'rgb') {
        const spread = off * (0.22 + 0.45 * power);
        ax = spread * jitter[0];
        bx = -spread * jitter[1];
        ay = off * 0.06 * jitter[2];
        by = off * 0.06 * jitter[3];
        if (live) {
          ax = off * scale * Math.abs(live.ax);
          bx = -off * scale * Math.abs(live.bx);
          ay = off * live.ay;
          by = off * live.by;
        }
        split = s.enableShadows ? 0.9 : 0.4;
      } else if (safeMode === 'scan') {
        const pass = 2.4 * pace;
        const cycle = pass * (1 + (1 - power) * 1.2);
        const local = clock % cycle;
        const height = 9 + 9 * power;
        if (local < pass) {
          const dir = Math.floor(clock / cycle) % 2 ? -1 : 1;
          const center = -height + (local / pass) * (100 + 2 * height);
          const trail = center - height * 1.5;
          const thin = height * 0.35;
          a = [center - height / 2, 100 - (center + height / 2)];
          b = [trail - thin / 2, 100 - (trail + thin / 2)];
          ax = off * scale * 1.5 * dir * (0.75 + 0.25 * Math.sin(clock * 23));
          bx = -ax * 0.5;
        }
        if (live) {
          b = [live.bTop, 100 - live.bTop - live.bHeight];
          bx = off * scale * live.bx * 1.4;
        }
      }

      a = fitBand(a[0], a[1]);
      b = fitBand(b[0], b[1]);
      const shadows = s.enableShadows && safeMode !== 'rgb';

      write('--glitch-a-top', `${a[0].toFixed(2)}%`);
      write('--glitch-a-bottom', `${a[1].toFixed(2)}%`);
      write('--glitch-b-top', `${b[0].toFixed(2)}%`);
      write('--glitch-b-bottom', `${b[1].toFixed(2)}%`);
      write('--glitch-a-x', `${ax.toFixed(2)}px`);
      write('--glitch-a-y', `${ay.toFixed(2)}px`);
      write('--glitch-b-x', `${bx.toFixed(2)}px`);
      write('--glitch-b-y', `${by.toFixed(2)}px`);
      write('--glitch-a-shadow', shadows ? `${(-ax / 2).toFixed(2)}px 0 ${s.shadowColors[0]}` : 'none');
      write('--glitch-b-shadow', shadows ? `${(-bx / 2).toFixed(2)}px 0 ${s.shadowColors[1]}` : 'none');
      write('--glitch-skew', `${(live ? s.skew * live.skew : 0).toFixed(2)}deg`);
      write('--glitch-alpha', alpha.toFixed(2));
      write('--glitch-split', String(split));

      raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (raf || !isActive(performance.now())) return;
      last = 0;
      raf = requestAnimationFrame(frame);
    };

    const onEnter = () => {
      hovering = true;
      wake();
    };
    const onLeave = () => {
      hovering = false;
    };
    const onClick = () => {
      const now = performance.now();
      const s = settingsRef.current;
      burstStart = now;
      burstEnd = now + Math.max(0.1, s.burstDuration) * 1000;
      event = makeEvent(now, stepLength(s.speed));
      nextStep = now;
      wake();
    };

    if (activeTrigger === 'hover') {
      root.addEventListener('pointerenter', onEnter);
      root.addEventListener('pointerleave', onLeave);
    }
    if (activeTrigger === 'click') root.addEventListener('click', onClick);

    const observer =
      typeof IntersectionObserver !== 'undefined'
        ? new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting;
            if (visible) wake();
          })
        : null;
    observer?.observe(root);
    wake();

    return () => {
      cancelAnimationFrame(raf);
      observer?.disconnect();
      root.removeEventListener('pointerenter', onEnter);
      root.removeEventListener('pointerleave', onLeave);
      root.removeEventListener('click', onClick);
      rest();
    };
  }, [safeMode, activeTrigger, charCount]);

  const rootStyle: GlitchStyle = {
    color,
    fontSize: typeof fontSize === 'number' ? `${fontSize}px` : fontSize,
    fontWeight,
    '--glitch-color-a': enableShadows ? shadowColors[0] : 'currentColor',
    '--glitch-color-b': enableShadows ? shadowColors[1] : 'currentColor',
    '--glitch-mask-a': bandMask('a'),
    '--glitch-mask-b': bandMask('b')
  };
  const layer = safeMode === 'rgb' ? 'split' : safeMode === 'noise' ? 'hidden' : 'band';

  return (
    <div ref={rootRef} className={`${ROOT_CLASS} ${className}`} style={rootStyle}>
      <span className={`${TEXT_CLASS} ${TEXT_LAYER[layer]}`} aria-hidden={chars ? 'true' : undefined}>
        {chars
          ? chars.map((char, i) => (
              <span
                key={i}
                ref={el => {
                  charRefs.current[i] = el;
                }}
                className={CHAR_CLASS}
              >
                {char}
              </span>
            ))
          : children}
      </span>
      {chars && <span className="sr-only">{children}</span>}
      <span className={`${SLICE_CLASS} ${SLICE_B[layer]}`} aria-hidden="true">
        {children}
      </span>
      <span className={`${SLICE_CLASS} ${SLICE_A[layer]}`} aria-hidden="true">
        {children}
      </span>
    </div>
  );
};

export default GlitchText;

'use client';

import { useEffect, useRef } from 'react';
import type { CSSProperties, ReactNode } from 'react';

type Variant = 'linear' | 'flow' | 'conic';

export interface GradientTextProps {
  children?: ReactNode;
  colors?: string[];
  animationSpeed?: number;
  variant?: Variant;
  angle?: number;
  direction?: 'horizontal' | 'vertical' | 'diagonal';
  scale?: number;
  yoyo?: boolean;
  glow?: number;
  showBorder?: boolean;
  borderWidth?: number;
  pauseOnHover?: boolean;
  followPointer?: boolean;
  className?: string;
  style?: CSSProperties;
}

interface Settings {
  colors: string[];
  speed: number;
  variant: Variant;
  angle: number;
  scale: number;
  yoyo: boolean;
  pauseOnHover: boolean;
  followPointer: boolean;
}

const VARIANTS: Variant[] = ['linear', 'flow', 'conic'];
const ANGLES: Record<string, number> = { horizontal: 90, vertical: 180, diagonal: 135 };
const TAU = Math.PI * 2;

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

export default function GradientText({
  children,
  colors = ['#5227FF', '#FF9FFC', '#B497CF'],
  animationSpeed = 8,
  variant = 'linear',
  angle = 90,
  direction,
  scale = 3,
  yoyo = true,
  glow = 0,
  showBorder = false,
  borderWidth = 1.5,
  pauseOnHover = false,
  followPointer = false,
  className = '',
  style
}: GradientTextProps) {
  const rootRef = useRef<HTMLSpanElement>(null);
  const settingsRef = useRef<Settings | null>(null);
  const wakeRef = useRef<(() => void) | null>(null);
  const palette = colors.length > 1 ? colors : [colors[0] ?? '#ffffff', colors[0] ?? '#ffffff'];

  settingsRef.current = {
    colors: palette,
    speed: Math.max(0.2, animationSpeed),
    variant: VARIANTS.includes(variant as Variant) ? (variant as Variant) : 'linear',
    angle: direction ? (ANGLES[direction] ?? angle) : angle,
    scale: clamp(scale, 1, 6),
    yoyo,
    pauseOnHover,
    followPointer
  };

  useEffect(() => {
    wakeRef.current?.();
  });

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
    const state = { time: 0, inside: false, visible: true, x: 0.5, y: 0.5, px: 0.5, py: 0.5, vx: 0, vy: 0, pull: 0 };
    let raf = 0;
    let last = 0;
    let alive = true;

    const paint = () => {
      const s = settingsRef.current!;
      const list = s.colors;
      const cycle = state.time / s.speed;
      let image;
      if (s.variant === 'flow') {
        const blobs = list.map((color, i) => {
          const spin = cycle * TAU;
          const rate = 0.55 + ((i * 0.618) % 1) * 0.5;
          let x = 50 + 44 * Math.sin(spin * rate + i * 2.1);
          let y = 50 + 40 * Math.sin(spin * (rate * 0.83 + 0.21) + i * 1.3);
          if (i === 0) {
            x += (state.px * 100 - x) * state.pull;
            y += (state.py * 100 - y) * state.pull;
          }
          return `radial-gradient(ellipse ${(22 + 12 * s.scale).toFixed(1)}% ${(60 + 30 * s.scale).toFixed(1)}% at ${x.toFixed(2)}% ${y.toFixed(2)}%, ${color} 0%, transparent 100%)`;
        });
        image = `${blobs.join(', ')}, linear-gradient(${s.angle}deg, ${list.join(', ')})`;
      } else if (s.variant === 'conic') {
        const sway = s.yoyo ? Math.sin(cycle * Math.PI) * 50 : cycle * 360;
        const cx = 50 + (state.px * 100 - 50) * state.pull;
        const cy = 260 + (state.py * 100 - 260) * state.pull;
        image = `repeating-conic-gradient(from ${(sway - 30).toFixed(2)}deg at ${cx.toFixed(2)}% ${cy.toFixed(2)}%, ${[...list, list[0]].map((color, i) => `${color} ${((i / list.length) * 60 * (3 / s.scale)).toFixed(2)}deg`).join(', ')})`;
      } else {
        const loop = [...list, list[0]];
        const period = 100 * s.scale;
        let offset;
        if (s.yoyo) {
          const swing = cycle % 2;
          const t = swing < 1 ? swing : 2 - swing;
          offset = (0.5 - Math.cos(Math.PI * t) / 2) * (period - 100);
        } else {
          offset = (cycle % 1) * period;
        }
        offset += (state.px - 0.5) * period * 0.5 * state.pull;
        const stops = loop.map((color, i) => `${color} ${((i / (loop.length - 1)) * period - offset).toFixed(2)}%`);
        image = `repeating-linear-gradient(${s.angle}deg, ${stops.join(', ')})`;
      }
      root.style.setProperty('--gt-gradient', image);
    };

    const tick = (now: number) => {
      raf = 0;
      if (!alive) return;
      const s = settingsRef.current!;
      const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
      last = now;
      const paused = reduce || (s.pauseOnHover && state.inside);
      if (!paused) state.time += dt;
      const target = s.followPointer && state.inside ? 1 : 0;
      state.pull += (target - state.pull) * (1 - Math.exp(-dt * 6));
      const stiffness = 160;
      state.vx += ((state.x - state.px) * stiffness - state.vx * 2 * Math.sqrt(stiffness)) * dt;
      state.vy += ((state.y - state.py) * stiffness - state.vy * 2 * Math.sqrt(stiffness)) * dt;
      state.px += state.vx * dt;
      state.py += state.vy * dt;
      paint();
      const settling = Math.abs(state.pull - target) > 0.001 || Math.abs(state.vx) + Math.abs(state.vy) > 0.001;
      if (!state.visible || (paused && !settling)) return;
      raf = requestAnimationFrame(tick);
    };

    const wake = () => {
      if (raf || !alive) return;
      last = performance.now();
      raf = requestAnimationFrame(tick);
    };
    wakeRef.current = () => {
      paint();
      wake();
    };

    const locate = (event: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      state.x = clamp((event.clientX - rect.left) / rect.width, 0, 1);
      state.y = clamp((event.clientY - rect.top) / rect.height, 0, 1);
    };
    const onEnter = (event: PointerEvent) => {
      locate(event);
      if (!state.inside) {
        state.px = state.x;
        state.py = state.y;
      }
      state.inside = true;
      wake();
    };
    const onMove = (event: PointerEvent) => {
      locate(event);
      wake();
    };
    const onLeave = () => {
      state.inside = false;
      wake();
    };

    const observer = new IntersectionObserver(entries => {
      state.visible = entries.some(entry => entry.isIntersecting);
      if (state.visible) wake();
    });
    observer.observe(root);
    root.addEventListener('pointerenter', onEnter);
    root.addEventListener('pointermove', onMove);
    root.addEventListener('pointerleave', onLeave);
    paint();
    wake();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      observer.disconnect();
      root.removeEventListener('pointerenter', onEnter);
      root.removeEventListener('pointermove', onMove);
      root.removeEventListener('pointerleave', onLeave);
      wakeRef.current = null;
    };
  }, []);

  const loop = [...palette, palette[0]];

  return (
    <span
      ref={rootRef}
      className={`relative inline-flex items-center justify-center max-w-full isolate ${showBorder ? 'px-[0.75em] py-[0.35em] rounded-full before:content-[] before:absolute before:inset-0 before:p-[var(--gt-border)] before:rounded-[inherit] before:[background-image:var(--gt-gradient)] before:[-webkit-mask:linear-gradient(#000_0_0)_content-box,linear-gradient(#000_0_0)] before:[-webkit-mask-composite:xor] before:[mask:linear-gradient(#000_0_0)_content-box_exclude,linear-gradient(#000_0_0)] before:pointer-events-none' : ''}${className ? ` ${className}` : ''}`}
      style={
        {
          '--gt-gradient': `linear-gradient(${direction ? (ANGLES[direction] ?? angle) : angle}deg, ${loop.join(', ')})`,
          '--gt-border': `${borderWidth}px`,
          '--gt-glow': clamp(glow, 0, 1),
          ...style
        } as CSSProperties
      }
    >
      <span className="relative inline-block">
        <span className="inline-block [background-image:var(--gt-gradient)] bg-clip-text [-webkit-background-clip:text] [-webkit-text-fill-color:transparent]">
          {children}
        </span>
        {glow > 0 ? (
          <span
            className="absolute inset-0 -z-10 [background-image:var(--gt-gradient)] bg-clip-text [-webkit-background-clip:text] [-webkit-text-fill-color:transparent] [filter:blur(0.3em)_saturate(1.4)] opacity-[var(--gt-glow)] pointer-events-none select-none"
            aria-hidden="true"
          >
            {children}
          </span>
        ) : null}
      </span>
    </span>
  );
}

'use client';

import React, { useCallback, useEffect, useId, useLayoutEffect, useMemo, useRef } from 'react';
import type { CSSProperties, ElementType } from 'react';
import { gsap } from 'gsap';

const useIsomorphicLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

const clamp = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v);

const SPOT_MASK = `radial-gradient(circle var(--mh-spot-r, 160px) at var(--mh-spot-x, 50%) var(--mh-spot-y, 50%), ${Array.from(
  { length: 9 },
  (_, i) => {
    const t = i / 8;
    const u = clamp((t - 0.1) / 0.9, 0, 1);
    return `rgba(0, 0, 0, ${(u * u * u * (u * (u * 6 - 15) + 10)).toFixed(3)}) ${(t * 100).toFixed(1)}%`;
  }
).join(', ')})`;

type Reveal = 'rise' | 'scale' | 'blur' | 'wipe' | 'fade' | 'none';
type Trigger = 'view' | 'mount' | 'hover';

export interface MaskedHeadingProps {
  text?: string;
  tag?: ElementType;
  mediaType?: 'image' | 'video';
  src?: string;
  poster?: string;
  fillScale?: number;
  parallax?: number;
  drift?: number;
  hoverZoom?: number;
  brightness?: number;
  saturation?: number;
  grayscale?: boolean;
  tint?: string;
  spotlight?: boolean;
  spotlightRadius?: number;
  outline?: boolean;
  outlineColor?: string;
  outlineWidth?: number;
  reveal?: Reveal;
  duration?: number;
  stagger?: number;
  trigger?: Trigger;
  align?: 'left' | 'center' | 'right';
  weight?: number;
  tracking?: number;
  lineHeight?: number;
  textScale?: number;
  className?: string;
  style?: CSSProperties;
  [key: string]: unknown;
}

interface Settings {
  fillScale: number;
  parallax: number;
  drift: number;
  hoverZoom: number;
  brightness: number;
  saturation: number;
  grayscale: boolean;
  textScale: number;
  spotlight: boolean;
}

interface GlyphBox {
  x: number;
  y: number;
  w: number;
  cx: number;
  cy: number;
  lc: number;
}

interface GlyphState {
  x: number;
  y: number;
  s: number;
}

const MaskedHeading: React.FC<MaskedHeadingProps> = ({
  text = 'Designed in the details',
  tag = 'h2',
  mediaType = 'image',
  src = '',
  poster = '',
  fillScale = 1.25,
  parallax = 26,
  drift = 18,
  hoverZoom = 0,
  brightness = 1,
  saturation = 1,
  grayscale = false,
  tint = '',
  spotlight = false,
  spotlightRadius = 160,
  outline = false,
  outlineColor = '',
  outlineWidth = 1,
  reveal = 'rise',
  duration = 1.1,
  stagger = 0.09,
  trigger = 'view',
  align = 'center',
  weight = 700,
  tracking = -0.03,
  lineHeight = 1.06,
  textScale = 0.115,
  className = '',
  style,
  ...rest
}: MaskedHeadingProps) => {
  const rootRef = useRef<HTMLElement | null>(null);
  const measureRef = useRef<HTMLSpanElement | null>(null);
  const revealRef = useRef<HTMLSpanElement | null>(null);
  const clipRef = useRef<HTMLSpanElement | null>(null);
  const mediaRef = useRef<HTMLSpanElement | null>(null);
  const wordRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const baseRefs = useRef<(HTMLElement | null)[]>([]);
  const glyphRefs = useRef<(SVGTextElement | null)[]>([]);
  const lineRefs = useRef<(SVGTextElement | null)[]>([]);
  const boxesRef = useRef<GlyphBox[]>([]);
  const statesRef = useRef<GlyphState[]>([]);
  const tweenRef = useRef<gsap.core.Animation | null>(null);
  const offsetRef = useRef({ x: 0, y: 0, tx: 0, ty: 0, zoom: 0, px: 0, py: 0, sx: 0, sy: 0, lit: false });
  const paintRef = useRef({ transform: '', filter: '', spot: '' });
  const wakeRef = useRef<() => void>(() => {});

  const clipId = `mh-${useId().replace(/[^a-zA-Z0-9_-]/g, '')}`;
  const words = useMemo(() => String(text).split(/\s+/).filter(Boolean), [text]);
  const glyphs = useMemo(() => words.flatMap((word, w) => Array.from(word).map(char => ({ char, w }))), [words]);

  const settingsRef = useRef<Settings>({
    fillScale: 1,
    parallax: 0,
    drift: 0,
    hoverZoom: 0,
    brightness: 1,
    saturation: 1,
    grayscale: false,
    textScale: 0.115,
    spotlight: false
  });
  settingsRef.current = {
    fillScale,
    parallax,
    drift,
    hoverZoom,
    brightness,
    saturation,
    grayscale,
    textScale,
    spotlight
  };

  const place = useCallback(() => {
    const root = rootRef.current;
    const media = mediaRef.current;
    if (!root || !media) return;
    const s = settingsRef.current;
    const off = offsetRef.current;
    const scale = s.fillScale * (1 + Math.max(0, off.zoom));
    const maxX = Math.max(0, ((scale - 1) / 2) * root.clientWidth);
    const maxY = Math.max(0, ((scale - 1) / 2) * root.clientHeight);

    const transform = `translate3d(${clamp(off.x, -maxX, maxX).toFixed(2)}px, ${clamp(off.y, -maxY, maxY).toFixed(2)}px, 0) scale(${scale.toFixed(4)})`;
    const filter = `brightness(${s.brightness}) saturate(${s.saturation})${s.grayscale ? ' grayscale(1)' : ''}`;
    const paint = paintRef.current;
    if (paint.transform !== transform) {
      paint.transform = transform;
      media.style.transform = transform;
    }
    if (paint.filter !== filter) {
      paint.filter = filter;
      media.style.filter = filter;
    }

    const clip = clipRef.current;
    if (clip && s.spotlight) {
      const spot = `${off.sx.toFixed(1)}px ${off.sy.toFixed(1)}px`;
      if (paint.spot !== spot) {
        paint.spot = spot;
        clip.style.setProperty('--mh-spot-x', `${off.sx.toFixed(1)}px`);
        clip.style.setProperty('--mh-spot-y', `${off.sy.toFixed(1)}px`);
      }
    }
  }, []);

  const renderGlyphs = useCallback(() => {
    const boxes = boxesRef.current;
    const states = statesRef.current;
    for (let i = 0; i < glyphRefs.current.length; i += 1) {
      const glyph = glyphRefs.current[i];
      if (!glyph) continue;
      const box = boxes[i];
      const st = states[i];
      if (!box || !st || (st.x === 0 && st.y === 0 && st.s === 1)) {
        if (glyph.hasAttribute('transform')) glyph.removeAttribute('transform');
        continue;
      }
      const s = Math.max(st.s, 0.0001);
      const tx = box.cx * (1 - s) + st.x * (box.cx - box.lc);
      const ty = box.cy * (1 - s) + st.y;
      glyph.setAttribute('transform', `translate(${tx.toFixed(2)} ${ty.toFixed(2)}) scale(${s.toFixed(4)})`);
    }
  }, []);

  const sync = useCallback(() => {
    const root = rootRef.current;
    const measure = measureRef.current;
    if (!root || !measure) return;
    const s = settingsRef.current;

    root.style.fontSize = `${clamp(root.clientWidth * s.textScale, 20, 200).toFixed(1)}px`;

    const cs = window.getComputedStyle(measure);
    const fontPx = parseFloat(cs.fontSize) || 48;
    const rootRect = root.getBoundingClientRect();
    const ratio = root.offsetWidth ? rootRect.width / root.offsetWidth || 1 : 1;
    const range = document.createRange();
    const boxes: GlyphBox[] = [];
    let index = 0;

    for (let w = 0; w < wordRefs.current.length; w += 1) {
      const box = wordRefs.current[w];
      const base = baseRefs.current[w];
      const node = box?.firstChild as Text | null | undefined;
      if (!box || !base || !node || node.nodeType !== 3) {
        index += Array.from(box?.textContent ?? '').length;
        continue;
      }
      const boxRect = box.getBoundingClientRect();
      const baseline = base.offsetTop;
      let offset = 0;
      for (const char of Array.from(node.data)) {
        range.setStart(node, offset);
        range.setEnd(node, offset + char.length);
        offset += char.length;
        const r = range.getBoundingClientRect();
        const x = box.offsetLeft + (r.left - boxRect.left) / ratio;
        const width = r.width / ratio;
        boxes[index] = { x, y: baseline, w: width, cx: x + width / 2, cy: baseline - fontPx * 0.36, lc: 0 };
        index += 1;
      }
    }
    const lines = new Map<number, { left: number; right: number }>();
    for (const box of boxes) {
      if (!box) continue;
      const line = lines.get(box.y) ?? { left: Infinity, right: -Infinity };
      line.left = Math.min(line.left, box.x);
      line.right = Math.max(line.right, box.x + box.w);
      lines.set(box.y, line);
    }
    for (const box of boxes) {
      if (!box) continue;
      const line = lines.get(box.y);
      if (line) box.lc = (line.left + line.right) / 2;
    }
    boxesRef.current = boxes;

    const write = (el: SVGTextElement) => {
      if (!el) return;
      el.style.fontFamily = cs.fontFamily;
      el.style.fontSize = cs.fontSize;
      el.style.fontWeight = cs.fontWeight;
      el.style.fontStyle = cs.fontStyle;
      el.style.letterSpacing = cs.letterSpacing;
    };
    for (let i = 0; i < boxes.length; i += 1) {
      const box = boxes[i];
      for (const el of [glyphRefs.current[i], lineRefs.current[i]]) {
        if (!el || !box) continue;
        el.setAttribute('x', box.x.toFixed(2));
        el.setAttribute('y', `${box.y}`);
        write(el);
      }
    }
    renderGlyphs();
    place();
  }, [place, renderGlyphs]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;

    let alive = true;
    const ro = new ResizeObserver(() => sync());
    ro.observe(root);
    if (document.fonts?.ready) document.fonts.ready.then(() => alive && sync()).catch(() => {});

    const motionQuery = window.matchMedia?.('(prefers-reduced-motion: reduce)');
    const off = offsetRef.current;
    let raf = 0;
    let last = 0;
    let clock = 0;
    let visible = true;
    let hovering = false;

    const frame = (now: number) => {
      raf = 0;
      const dt = last ? Math.min(0.05, (now - last) / 1000) : 0;
      last = now;
      const s = settingsRef.current;
      const still = !!motionQuery?.matches;

      if (still) {
        off.x = 0;
        off.y = 0;
        off.zoom = 0;
      } else {
        clock += dt;
        const dx = Math.sin(clock * 0.21) * s.drift;
        const dy = Math.cos(clock * 0.17) * s.drift * 0.6;
        const ease = 1 - Math.exp(-dt / 0.18);
        off.x += (off.tx + dx - off.x) * ease;
        off.y += (off.ty + dy - off.y) * ease;
        off.zoom += ((hovering ? s.hoverZoom : 0) - off.zoom) * (1 - Math.exp(-dt / 0.35));
      }

      if (s.spotlight) {
        const w = root.clientWidth;
        const h = root.clientHeight;
        let gx = w / 2;
        let gy = h / 2;
        if (hovering) {
          gx = off.px;
          gy = off.py;
        } else if (!still) {
          gx = w * (0.5 + 0.36 * Math.sin(clock * 0.37));
          gy = h * (0.5 + 0.22 * Math.sin(clock * 0.61 + 0.9));
        }
        if (!off.lit || still) {
          off.sx = gx;
          off.sy = gy;
          off.lit = true;
        } else {
          const follow = 1 - Math.exp(-dt / (hovering ? 0.12 : 0.6));
          off.sx += (gx - off.sx) * follow;
          off.sy += (gy - off.sy) * follow;
        }
      } else {
        off.lit = false;
      }

      place();
      if (visible && !still && alive) raf = requestAnimationFrame(frame);
    };

    const wake = () => {
      if (raf || !alive) return;
      last = 0;
      raf = requestAnimationFrame(frame);
    };
    wakeRef.current = wake;

    const onMove = (e: PointerEvent) => {
      const s = settingsRef.current;
      const r = root.getBoundingClientRect();
      const nx = ((e.clientX - r.left) / (r.width || 1)) * 2 - 1;
      const ny = ((e.clientY - r.top) / (r.height || 1)) * 2 - 1;
      off.tx = clamp(nx, -1, 1) * -Math.max(0, s.parallax);
      off.ty = clamp(ny, -1, 1) * -Math.max(0, s.parallax);
      off.px = ((e.clientX - r.left) / (r.width || 1)) * root.clientWidth;
      off.py = ((e.clientY - r.top) / (r.height || 1)) * root.clientHeight;
      if (s.spotlight) wake();
    };

    const onEnter = (e: PointerEvent) => {
      hovering = e.pointerType !== 'touch';
      onMove(e);
      wake();
    };

    const onLeave = () => {
      hovering = false;
      off.tx = 0;
      off.ty = 0;
      wake();
    };

    const io = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) wake();
    });
    io.observe(root);

    root.addEventListener('pointermove', onMove);
    root.addEventListener('pointerenter', onEnter);
    root.addEventListener('pointerleave', onLeave);
    wake();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      raf = 0;
      wakeRef.current = () => {};
      ro.disconnect();
      io.disconnect();
      root.removeEventListener('pointermove', onMove);
      root.removeEventListener('pointerenter', onEnter);
      root.removeEventListener('pointerleave', onLeave);
    };
  }, [place, sync]);

  useEffect(() => {
    wakeRef.current();
  });

  useEffect(() => {
    const video = mediaRef.current?.querySelector('video');
    if (video && window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches) video.pause();
  }, [mediaType, src]);

  useIsomorphicLayoutEffect(() => {
    sync();
  }, [sync, words, tag, align, weight, tracking, lineHeight, textScale, outline]);

  useIsomorphicLayoutEffect(() => {
    const root = rootRef.current;
    const layer = revealRef.current;
    if (!root || !layer) return undefined;
    const states: GlyphState[] = glyphs.map(() => ({ x: 0, y: 0, s: 1 }));
    statesRef.current = states;
    if (!states.length) return undefined;

    const em = () => parseFloat(window.getComputedStyle(root).fontSize) || 48;
    const wordDelay = (i: number) => glyphs[i].w * stagger;
    const letterDelay = (i: number) => i * stagger * 0.35;

    const clearLayer = () => {
      gsap.set(layer, { opacity: 1, scale: 1 });
      layer.style.clipPath = '';
      layer.style.filter = '';
    };

    const settle = () => {
      states.forEach(st => {
        st.x = 0;
        st.y = 0;
        st.s = 1;
      });
      renderGlyphs();
      clearLayer();
    };

    const rest = () => {
      const size = em();
      if (reveal === 'rise') {
        states.forEach(st => {
          st.y = size * 1.15;
        });
      } else if (reveal === 'scale') {
        states.forEach(st => {
          st.y = size * 0.1;
          st.s = 0;
        });
      } else if (reveal === 'blur') {
        states.forEach(st => {
          st.x = 0.22;
        });
        gsap.set(layer, { opacity: 0 });
        layer.style.filter = `blur(${(size * 0.3).toFixed(2)}px)`;
      } else if (reveal === 'wipe') {
        layer.style.clipPath = 'inset(0% 100% 0% 0%)';
      } else if (reveal === 'fade') {
        gsap.set(layer, { opacity: 0, scale: 1.08 });
      }
      renderGlyphs();
    };

    const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
    if (reveal === 'none' || reduce) {
      settle();
      return undefined;
    }

    const play = () => {
      tweenRef.current?.kill();
      const size = em();
      if (reveal === 'rise') {
        clearLayer();
        tweenRef.current = gsap.fromTo(
          states,
          { x: 0, y: size * 1.15, s: 1 },
          { y: 0, duration, stagger: wordDelay, ease: 'power4.out', overwrite: 'auto', onUpdate: renderGlyphs }
        );
        renderGlyphs();
      } else if (reveal === 'scale') {
        clearLayer();
        tweenRef.current = gsap.fromTo(
          states,
          { x: 0, y: size * 0.1, s: 0 },
          { y: 0, s: 1, duration, stagger: letterDelay, ease: 'expo.out', overwrite: 'auto', onUpdate: renderGlyphs }
        );
        renderGlyphs();
      } else if (reveal === 'blur') {
        const focus = { blur: size * 0.3, opacity: 0 };
        gsap.set(layer, { scale: 1, opacity: 0 });
        layer.style.clipPath = '';
        layer.style.filter = `blur(${focus.blur.toFixed(2)}px)`;
        const timeline = gsap.timeline({ onUpdate: renderGlyphs });
        timeline.fromTo(states, { x: 0.22, y: 0, s: 1 }, { x: 0, duration: duration * 1.2, ease: 'expo.out' }, 0);
        timeline.to(
          focus,
          {
            blur: 0,
            opacity: 1,
            duration: duration * 1.2,
            ease: 'power2.out',
            onUpdate: () => {
              layer.style.filter = focus.blur > 0.05 ? `blur(${focus.blur.toFixed(2)}px)` : '';
              layer.style.opacity = focus.opacity.toFixed(3);
            }
          },
          0
        );
        tweenRef.current = timeline;
        renderGlyphs();
      } else if (reveal === 'wipe') {
        settle();
        layer.style.clipPath = 'inset(0% 100% 0% 0%)';
        const state = { p: 100 };
        tweenRef.current = gsap.to(state, {
          p: 0,
          duration,
          ease: 'power3.inOut',
          overwrite: 'auto',
          onUpdate: () => {
            layer.style.clipPath = `inset(0% ${state.p}% 0% 0%)`;
          }
        });
      } else {
        settle();
        tweenRef.current = gsap.fromTo(
          layer,
          { opacity: 0, scale: 1.08 },
          { opacity: 1, scale: 1, duration, ease: 'power3.out', overwrite: 'auto' }
        );
      }
    };

    if (trigger === 'hover') {
      settle();
      root.addEventListener('pointerenter', play);
      return () => {
        root.removeEventListener('pointerenter', play);
        tweenRef.current?.kill();
      };
    }

    if (trigger === 'view') {
      settle();
      rest();
      const io = new IntersectionObserver(
        entries => {
          if (entries.some(e => e.isIntersecting)) {
            play();
            io.disconnect();
          }
        },
        { threshold: 0.25 }
      );
      io.observe(root);
      return () => {
        io.disconnect();
        tweenRef.current?.kill();
      };
    }

    play();
    return () => tweenRef.current?.kill();
  }, [reveal, trigger, duration, stagger, glyphs, renderGlyphs]);

  const Tag = tag;

  return (
    <Tag
      ref={rootRef}
      className={`relative w-full m-0 p-0 antialiased [text-wrap:balance] ${className}`.trim()}
      style={{
        textAlign: align,
        fontWeight: weight,
        letterSpacing: `${tracking}em`,
        lineHeight,
        ...style
      }}
      {...rest}
    >
      <span ref={measureRef} className="text-transparent">
        {words.map((word, i) => (
          <span
            key={`${word}-${i}`}
            ref={(el: HTMLSpanElement | null) => {
              wordRefs.current[i] = el;
            }}
            className="inline-block whitespace-pre [&:not(:last-child)]:after:content-['_']"
          >
            {word}
            <i
              ref={(el: HTMLElement | null) => {
                baseRefs.current[i] = el;
              }}
              className="inline-block w-0 h-0"
            />
          </span>
        ))}
      </span>

      <svg className="absolute w-0 h-0 overflow-hidden" aria-hidden="true" focusable="false">
        <defs>
          <clipPath id={clipId} clipPathUnits="userSpaceOnUse">
            {glyphs.map((glyph, i) => (
              <text
                key={i}
                ref={(el: SVGTextElement | null) => {
                  glyphRefs.current[i] = el;
                }}
              >
                {glyph.char}
              </text>
            ))}
          </clipPath>
        </defs>
      </svg>

      <span ref={revealRef} className="absolute inset-0 block pointer-events-none">
        <span
          ref={clipRef}
          className="absolute inset-0 block"
          style={
            {
              clipPath: `url(#${clipId})`,
              ['--mh-spot-r' as string]: `${Math.max(1, spotlightRadius)}px`
            } as CSSProperties
          }
        >
          <span
            ref={mediaRef}
            className="absolute inset-0 block [background:color-mix(in_srgb,currentColor_10%,transparent)] [will-change:transform,filter]"
          >
            {mediaType === 'video' ? (
              <video
                className="block w-full h-full object-cover select-none"
                src={src || undefined}
                poster={poster || undefined}
                autoPlay
                muted
                loop
                playsInline
              />
            ) : (
              <img
                className="block w-full h-full object-cover select-none"
                src={src || undefined}
                alt=""
                draggable={false}
              />
            )}
          </span>
          {tint ? (
            <span className="absolute inset-0 block mix-blend-color pointer-events-none" style={{ background: tint }} />
          ) : null}
          {spotlight ? (
            <>
              <span
                className="absolute inset-0 block pointer-events-none bg-[#808080] mix-blend-saturation"
                style={{ maskImage: SPOT_MASK, WebkitMaskImage: SPOT_MASK }}
              />
              <span
                className="absolute inset-0 block pointer-events-none bg-black opacity-55"
                style={{ maskImage: SPOT_MASK, WebkitMaskImage: SPOT_MASK }}
              />
            </>
          ) : null}
        </span>
      </span>

      {outline ? (
        <svg
          className="absolute inset-0 w-full h-full overflow-visible pointer-events-none fill-none [stroke-linejoin:round]"
          aria-hidden="true"
          focusable="false"
          style={{ stroke: outlineColor || 'currentColor', strokeWidth: Math.max(0, outlineWidth) }}
        >
          {glyphs.map((glyph, i) => (
            <text
              key={i}
              ref={(el: SVGTextElement | null) => {
                lineRefs.current[i] = el;
              }}
            >
              {glyph.char}
            </text>
          ))}
        </svg>
      ) : null}
    </Tag>
  );
};

export default MaskedHeading;

'use client';

import { useEffect, useRef, type CSSProperties } from 'react';

export interface ParticleTextProps {
  text?: string;
  particleSize?: number;
  density?: number;
  color?: string;
  highlightColor?: string;
  highlightMode?: 'motion' | 'gradient';
  shape?: 'circle' | 'square' | 'line';
  intro?: 'gather' | 'rain' | 'spiral' | 'scan';
  scatter?: number;
  gatherDuration?: number;
  stagger?: number;
  clickBurst?: boolean;
  burstStrength?: number;
  pointerRepel?: number;
  repelRadius?: number;
  idleDrift?: number;
  trigger?: 'mount' | 'hover' | 'click';
  fontSize?: number | string;
  fontWeight?: number | string;
  fontFamily?: string;
  glow?: boolean;
  className?: string;
  style?: CSSProperties;
}

type Settings = Required<Omit<ParticleTextProps, 'className' | 'style'>>;
type Intro = Settings['intro'];
type Shape = Settings['shape'];
type Rgb = { r: number; g: number; b: number };
type Target = { x: number; y: number; alpha: number };
type Particle = {
  x: number;
  y: number;
  startX: number;
  startY: number;
  targetX: number;
  targetY: number;
  weight: number;
  tone: number;
  seed: number;
  depth: number;
  delay: number;
  ox: number;
  oy: number;
  vx: number;
  vy: number;
  angle: number;
  length: number;
  radius: number;
  heading: number;
  startRadius: number;
  swirl: number;
};

const INHERIT = /^(currentcolor|inherit)$/i;
const TONES = 12;
const FADES = 8;
const HEAT_RANGE = 36;
const HEAT_DEADZONE = 3;
const TAU = Math.PI * 2;
const REST_ANGLE = -Math.PI / 4;
const BURST_SPRING = 18;
const BURST_DAMPING = 7.5;
const SCAN_FADE = [0, 0.12, 0.42, 0.78, 1, 0.78, 0.42, 0.12, 0];
const FADE_FLOOR: Record<Intro, number> = { gather: 0, rain: 0.55, spiral: 0.45, scan: 0.35 };

const clamp = (value: number, min: number, max: number): number => Math.min(Math.max(value, min), max);
const easeOutCubic = (t: number): number => 1 - Math.pow(1 - t, 3);
const easeInFall = (t: number): number => Math.pow(t, 1.7);
const easeInOutCubic = (t: number): number => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
const fadeAlpha = (level: number): number => 0.35 + (0.65 * level) / (FADES - 1);
const wrapHalfTurn = (angle: number): number => (((angle % Math.PI) + Math.PI * 1.5) % Math.PI) - Math.PI / 2;

const resolveFontSize = (
  value: number | string,
  container: HTMLDivElement,
  fontWeight: number | string,
  fontFamily: string
): number => {
  if (typeof value === 'number') return value;

  const probe = document.createElement('span');
  probe.textContent = 'M';
  probe.style.position = 'absolute';
  probe.style.visibility = 'hidden';
  probe.style.pointerEvents = 'none';
  probe.style.fontSize = value;
  probe.style.fontWeight = String(fontWeight);
  probe.style.fontFamily = fontFamily;
  container.appendChild(probe);
  const size = parseFloat(window.getComputedStyle(probe).fontSize) || 96;
  probe.remove();
  return size;
};

const waitForFonts = async (font: string): Promise<void> => {
  if (!('fonts' in document)) return;

  try {
    await document.fonts.load(font);
  } catch {}

  await document.fonts.ready;
};

const ParticleText = ({
  text = 'React Bits',
  particleSize = 2,
  density = 4,
  color = 'currentColor',
  highlightColor = '#ff5a36',
  highlightMode = 'motion',
  shape = 'circle',
  intro = 'gather',
  scatter = 180,
  gatherDuration = 1600,
  stagger = 420,
  clickBurst = true,
  burstStrength = 1,
  pointerRepel = 40,
  repelRadius = 120,
  idleDrift = 0.7,
  trigger = 'mount',
  fontSize = 'clamp(3rem, 12vw, 8rem)',
  fontWeight = 800,
  fontFamily = 'inherit',
  glow = true,
  className = '',
  style
}: ParticleTextProps) => {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const settingsRef = useRef<Settings | null>(null);
  const wakeRef = useRef<() => void>(() => {});

  useEffect(() => {
    settingsRef.current = {
      text,
      particleSize,
      density,
      color,
      highlightColor,
      highlightMode,
      shape,
      intro,
      scatter,
      gatherDuration,
      stagger,
      clickBurst,
      burstStrength,
      pointerRepel,
      repelRadius,
      idleDrift,
      trigger,
      fontSize,
      fontWeight,
      fontFamily,
      glow
    };
    wakeRef.current();
  });

  useEffect(() => {
    const container = containerRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    const layer = document.createElement('canvas');
    const layerCtx = layer.getContext('2d');
    const probe = document.createElement('canvas');
    probe.width = 1;
    probe.height = 1;
    const probeCtx = probe.getContext('2d', { willReadFrequently: true });
    if (!container || !canvas || !ctx || !layerCtx || !probeCtx) return undefined;

    const motionQuery = window.matchMedia?.('(prefers-reduced-motion: reduce)');
    let reducedMotion = !!motionQuery?.matches;
    let particles: Particle[] = [];
    let raf = 0;
    let sampleFrame = 0;
    let buildId = 0;
    let introPending = true;
    let sampledKey = '';
    let sampledText = '';
    let requestedSize = '';
    let gathering = false;
    let gatherStart = 0;
    let introMode: Intro = 'gather';
    let bursting = false;
    let width = 0;
    let height = 0;
    let dpr = 1;
    let last = 0;
    let visible = true;
    let alive = true;
    let colorKey = '';
    let palette: string[] = [];
    let glowColor = '#000000';
    let accent: Rgb = { r: 0, g: 0, b: 0 };
    const bounds = { left: 0, right: 0, top: 0, bottom: 0 };
    const swirl = { x: 0, y: 0, aspect: 1 };
    const scan = { from: 0, to: 0, top: 0, bottom: 0, duration: 1 };
    const buckets: Particle[][] = Array.from({ length: TONES * FADES }, () => []);
    const pointer = { active: false, x: 0, y: 0, smoothX: 0, smoothY: 0 };

    const family = (s: Settings): string =>
      !s.fontFamily || s.fontFamily === 'inherit'
        ? window.getComputedStyle(container).fontFamily || 'sans-serif'
        : s.fontFamily;
    const layoutKey = (s: Settings) => [s.text, s.fontSize, s.fontWeight, family(s), s.density].join('|');
    const sizeKey = () => {
      const rect = container.getBoundingClientRect();
      return `${Math.floor(rect.width)}x${Math.floor(rect.height)}@${Math.min(window.devicePixelRatio || 1, 2)}`;
    };

    const toRgb = (value: string): Rgb => {
      probeCtx.clearRect(0, 0, 1, 1);
      probeCtx.fillStyle = '#000000';
      probeCtx.fillStyle = value;
      probeCtx.fillRect(0, 0, 1, 1);
      const [r, g, b] = probeCtx.getImageData(0, 0, 1, 1).data;
      return { r, g, b };
    };

    const ensureColors = (s: Settings) => {
      const current = window.getComputedStyle(container).color || '#000000';
      const pick = (value: string) => (!value || INHERIT.test(String(value).trim()) ? current : value);
      const base = pick(s.color);
      const highlight = pick(s.highlightColor);
      const key = `${base}|${highlight}`;
      if (key === colorKey) return;
      colorKey = key;
      const from = toRgb(base);
      accent = toRgb(highlight);
      glowColor = `rgb(${accent.r}, ${accent.g}, ${accent.b})`;
      palette = Array.from({ length: TONES }, (_, i) => {
        const t = i / (TONES - 1);
        const r = Math.round(from.r + (accent.r - from.r) * t);
        const g = Math.round(from.g + (accent.g - from.g) * t);
        const b = Math.round(from.b + (accent.b - from.b) * t);
        return `rgb(${r}, ${g}, ${b})`;
      });
    };

    const travelTime = (s: Settings, particle: Particle): number => {
      if (reducedMotion) return 1;
      if (introMode === 'scan') return s.gatherDuration * 0.4;
      if (introMode === 'rain') return s.gatherDuration * (0.45 + particle.depth * 0.3);
      return s.gatherDuration;
    };

    const startIntro = (initial: boolean) => {
      const s = settingsRef.current;
      if (!particles.length || !s) return;
      introMode = s.intro;
      const spread = reducedMotion ? 0 : s.scatter;
      const tall = Math.max(1, bounds.bottom - bounds.top);
      swirl.x = (bounds.left + bounds.right) / 2;
      swirl.y = (bounds.top + bounds.bottom) / 2;
      swirl.aspect = clamp(width / Math.max(1, height), 1, 2.5);
      scan.from = bounds.left - 24;
      scan.to = bounds.right + 24;
      scan.top = bounds.top - tall * 0.3;
      scan.bottom = bounds.bottom + tall * 0.3;
      scan.duration = Math.max(200, s.gatherDuration * 0.8);
      let reach = 1;

      if (introMode === 'spiral') {
        for (const particle of particles) {
          const dx = particle.targetX - swirl.x;
          const dy = (particle.targetY - swirl.y) * swirl.aspect;
          particle.radius = Math.hypot(dx, dy);
          particle.heading = Math.atan2(dy, dx);
          reach = Math.max(reach, particle.radius);
        }
      }

      for (const particle of particles) {
        let delay = particle.seed * s.stagger;
        let startX;
        let startY;

        if (introMode === 'rain') {
          startX = particle.targetX + (particle.depth - 0.9) * 16;
          startY = -12 - particle.depth * 30 - particle.seed * height * 0.22;
          delay = particle.seed * s.stagger * 1.3;
        } else if (introMode === 'spiral') {
          particle.startRadius = particle.radius * (1.04 + particle.depth * 0.22) + spread * 0.3 * particle.seed;
          particle.swirl = (1.5 + 2.6 * (1 - particle.radius / reach)) * (0.85 + particle.seed * 0.3);
          const angle = particle.heading + particle.swirl;
          startX = swirl.x + Math.cos(angle) * particle.startRadius;
          startY = swirl.y + (Math.sin(angle) * particle.startRadius) / swirl.aspect;
          delay = particle.seed * s.stagger;
        } else if (introMode === 'scan') {
          const along = (particle.targetX - scan.from) / Math.max(1, scan.to - scan.from);
          startX = particle.targetX + 3 + particle.seed * 8;
          startY = scan.top + ((particle.seed * 7.31 + particle.depth * 3.7) % 1) * (scan.bottom - scan.top);
          delay = along * scan.duration + particle.seed * s.stagger * 0.15;
        } else {
          const angle = particle.seed * TAU;
          const distance = spread * (0.35 + particle.depth * 0.75);
          startX = particle.targetX + Math.cos(angle) * distance + (particle.seed - 0.5) * spread * 0.45;
          startY = particle.targetY + Math.sin(angle) * distance + (particle.depth - 0.9) * spread * 0.45;
        }

        particle.startX = startX;
        particle.startY = startY;
        particle.delay = reducedMotion ? 0 : delay;
        if (initial) {
          particle.x = startX;
          particle.y = startY;
        }
      }

      gatherStart = performance.now();
      gathering = true;
      wake();
    };

    const burst = (x: number, y: number) => {
      const s = settingsRef.current;
      if (!s || !particles.length) return;
      const strength = Math.max(0, Number(s.burstStrength) || 0);
      if (!strength) return;
      const radius = 90 + 70 * Math.sqrt(strength) + s.repelRadius * 0.25;

      for (const particle of particles) {
        const dx = particle.x - x;
        const dy = particle.y - y;
        const distance = Math.hypot(dx, dy);
        if (distance > radius) continue;
        const falloff = 1 - distance / radius;
        const power = 950 * strength * (0.2 + 0.8 * falloff * falloff) * (0.65 + particle.depth * 0.45);
        const angle = Math.atan2(dy, dx) + (particle.seed - 0.5) * 0.9;
        particle.vx += Math.cos(angle) * power;
        particle.vy += Math.sin(angle) * power;
      }

      bursting = true;
      wake();
    };

    const drawGroup = (target: CanvasRenderingContext2D, group: Particle[], base: number, shape: Shape) => {
      target.beginPath();
      if (shape === 'line') {
        for (const particle of group) {
          const dx = Math.cos(particle.angle) * particle.length * 0.5;
          const dy = Math.sin(particle.angle) * particle.length * 0.5;
          target.moveTo(particle.x - dx, particle.y - dy);
          target.lineTo(particle.x + dx, particle.y + dy);
        }
        target.stroke();
        return;
      }

      const square = shape === 'square';
      for (const particle of group) {
        const size = square ? base : Math.max(0.6, base * (0.75 + particle.weight * 0.45));
        if (square || size <= 2.1) {
          target.rect(particle.x - size / 2, particle.y - size / 2, size, size);
        } else {
          target.moveTo(particle.x + size / 2, particle.y);
          target.arc(particle.x, particle.y, size / 2, 0, TAU);
        }
      }
      target.fill();
    };

    const drawScan = (now: number, s: Settings): boolean => {
      const progress = (now - gatherStart) / scan.duration;
      if (introMode !== 'scan' || progress < 0 || progress > 1.3 || reducedMotion) return false;
      const x = scan.from + (scan.to - scan.from) * clamp(progress, 0, 1);
      const alpha = clamp(progress / 0.08, 0, 1) * clamp((1.3 - progress) / 0.3, 0, 1);
      const gradient = ctx.createLinearGradient(0, scan.top, 0, scan.bottom);
      SCAN_FADE.forEach((level, i) => {
        gradient.addColorStop(i / (SCAN_FADE.length - 1), `rgba(${accent.r}, ${accent.g}, ${accent.b}, ${level})`);
      });
      ctx.globalAlpha = alpha * 0.85;
      ctx.fillStyle = gradient;
      if (s.glow) {
        ctx.shadowColor = glowColor;
        ctx.shadowBlur = 8 * dpr;
      }
      ctx.fillRect(x - 0.75, scan.top, 1.5, scan.bottom - scan.top);
      ctx.shadowBlur = 0;
      ctx.shadowColor = 'transparent';
      ctx.globalAlpha = 1;
      return true;
    };

    const step = (now: number): boolean => {
      const s = settingsRef.current;
      if (!s) return false;
      const dt = last ? Math.min(0.05, Math.max(0, (now - last) / 1000)) : 1 / 60;
      last = now;
      ensureColors(s);

      const frames = Math.max(dt * 60, 0.001);
      const follow = reducedMotion ? 1 : 1 - Math.pow(0.78, frames);
      const chase = 1 - Math.pow(0.82, frames);
      const turn = 1 - Math.pow(0.72, frames);
      pointer.smoothX += (pointer.x - pointer.smoothX) * chase;
      pointer.smoothY += (pointer.y - pointer.smoothY) * chase;

      const repel = pointer.active && !reducedMotion && s.pointerRepel > 0 && s.repelRadius > 0;
      const drift = !reducedMotion && s.idleDrift > 0;
      const motionHeat = s.highlightMode !== 'gradient';
      const lines = s.shape === 'line';
      const floor = gathering ? (FADE_FLOOR[introMode] ?? 0) : 0;
      const time = now * 0.001;
      const sizeBase = Math.max(0.1, Number(s.particleSize) || 0);
      const restLength = Math.max(2, sizeBase * 0.8 + Math.max(2, Math.floor(Number(s.density) || 0)) * 0.7);
      let complete = true;
      let moving = false;
      let settling = false;

      for (const bucket of buckets) bucket.length = 0;

      for (const particle of particles) {
        let baseX = particle.targetX;
        let baseY = particle.targetY;
        let progress = 1;
        let hidden = false;

        if (gathering) {
          const local = (now - gatherStart - particle.delay) / Math.max(1, travelTime(s, particle));
          progress = clamp(local, 0, 1);
          if (introMode === 'scan' && local < 0) hidden = true;
          if (introMode === 'spiral') {
            const eased = easeInOutCubic(progress);
            const radius = particle.startRadius + (particle.radius - particle.startRadius) * eased;
            const angle = particle.heading + particle.swirl * (1 - eased);
            baseX = swirl.x + Math.cos(angle) * radius;
            baseY = swirl.y + (Math.sin(angle) * radius) / swirl.aspect;
          } else {
            const eased = introMode === 'rain' ? easeInFall(progress) : easeOutCubic(progress);
            baseX = particle.startX + (particle.targetX - particle.startX) * eased;
            baseY = particle.startY + (particle.targetY - particle.startY) * eased;
          }
          if (progress < 1) complete = false;
        } else if (drift) {
          baseX += Math.sin(time * 0.9 + particle.seed * 10) * s.idleDrift * particle.depth;
          baseY += Math.cos(time * 0.75 + particle.depth * 10) * s.idleDrift * particle.depth;
        }

        if (bursting) {
          particle.vx += (-BURST_SPRING * particle.ox - BURST_DAMPING * particle.vx) * dt;
          particle.vy += (-BURST_SPRING * particle.oy - BURST_DAMPING * particle.vy) * dt;
          particle.ox += particle.vx * dt;
          particle.oy += particle.vy * dt;
          if (
            Math.abs(particle.ox) + Math.abs(particle.oy) > 0.05 ||
            Math.abs(particle.vx) + Math.abs(particle.vy) > 1
          ) {
            settling = true;
          } else {
            particle.ox = 0;
            particle.oy = 0;
            particle.vx = 0;
            particle.vy = 0;
          }
          baseX += particle.ox;
          baseY += particle.oy;
        }

        if (repel) {
          const dx = baseX - pointer.smoothX;
          const dy = baseY - pointer.smoothY;
          const distance = Math.hypot(dx, dy);
          if (distance > 0 && distance < s.repelRadius) {
            const force = Math.pow(1 - distance / s.repelRadius, 2) * s.pointerRepel;
            baseX += (dx / distance) * force;
            baseY += (dy / distance) * force;
          }
        }

        const moveX = (baseX - particle.x) * follow;
        const moveY = (baseY - particle.y) * follow;
        particle.x += moveX;
        particle.y += moveY;
        if (Math.abs(moveX) + Math.abs(moveY) > 0.02) moving = true;

        if (lines) {
          const speed = Math.hypot(moveX, moveY) / frames;
          const aim = speed > 0.3 ? Math.atan2(moveY, moveX) : REST_ANGLE;
          const offset = wrapHalfTurn(aim - particle.angle);
          particle.angle += offset * turn;
          if (Math.abs(offset) > 0.01) moving = true;
          particle.length = restLength + Math.min(restLength * 4, speed * 1.6);
        }

        if (hidden) continue;

        const heat = motionHeat
          ? clamp(
              (Math.hypot(particle.x - particle.targetX, particle.y - particle.targetY) - HEAT_DEADZONE) / HEAT_RANGE,
              0,
              1
            )
          : particle.tone;
        const tone = Math.round(heat * (TONES - 1));
        const fade = Math.round((floor + (1 - floor) * progress) * (FADES - 1));
        buckets[fade * TONES + tone].push(particle);
      }

      if (gathering && complete) gathering = false;
      if (bursting && !settling) bursting = false;

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.globalAlpha = 1;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const strokeWidth = Math.max(1, sizeBase * 0.65);
      if (lines) {
        ctx.lineWidth = strokeWidth;
        ctx.lineCap = 'round';
      }

      if (s.glow) {
        layerCtx.setTransform(1, 0, 0, 1, 0, 0);
        layerCtx.clearRect(0, 0, layer.width, layer.height);
        layerCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
        layerCtx.fillStyle = glowColor;
        layerCtx.strokeStyle = glowColor;
        layerCtx.lineWidth = strokeWidth;
        layerCtx.lineCap = 'round';
        let lit = false;
        for (let fade = 0; fade < FADES; fade++) {
          for (let tone = 1; tone < TONES; tone++) {
            const group = buckets[fade * TONES + tone];
            if (!group.length) continue;
            layerCtx.globalAlpha = (tone / (TONES - 1)) * fadeAlpha(fade);
            drawGroup(layerCtx, group, sizeBase, s.shape);
            lit = true;
          }
        }
        layerCtx.globalAlpha = 1;
        if (lit) {
          ctx.shadowColor = glowColor;
          ctx.shadowBlur = (3 + sizeBase * 1.5) * dpr;
          ctx.drawImage(layer, 0, 0, width, height);
          ctx.shadowBlur = 0;
          ctx.shadowColor = 'transparent';
        }
      }

      for (let fade = 0; fade < FADES; fade++) {
        ctx.globalAlpha = fadeAlpha(fade);
        for (let tone = 0; tone < TONES; tone++) {
          const group = buckets[fade * TONES + tone];
          if (!group.length) continue;
          if (lines) ctx.strokeStyle = palette[tone];
          else ctx.fillStyle = palette[tone];
          drawGroup(ctx, group, sizeBase, s.shape);
        }
      }
      ctx.globalAlpha = 1;

      const scanning = drawScan(now, s);

      return gathering || moving || repel || drift || bursting || scanning;
    };

    const frame = (now: number) => {
      raf = 0;
      if (!alive) return;
      const s = settingsRef.current;
      if (s) {
        const key = layoutKey(s);
        if (key !== sampledKey) {
          queueSample(s.text !== sampledText);
          sampledKey = key;
          sampledText = s.text;
        }
      }
      const busy = step(now);
      if (busy && visible && alive) raf = requestAnimationFrame(frame);
    };

    function wake(): void {
      if (raf || !visible || !alive) return;
      last = 0;
      raf = requestAnimationFrame(frame);
    }
    wakeRef.current = wake;

    const sampleText = async (): Promise<void> => {
      const s = settingsRef.current;
      if (!s) return;
      const currentBuild = ++buildId;
      const rect = container.getBoundingClientRect();
      const nextWidth = Math.floor(rect.width);
      const nextHeight = Math.floor(rect.height);
      requestedSize = sizeKey();
      sampledKey = layoutKey(s);
      sampledText = s.text;

      if (nextWidth <= 0 || nextHeight <= 0) return;

      const nextDpr = Math.min(window.devicePixelRatio || 1, 2);
      const resolvedFamily = family(s);
      let resolvedSize = resolveFontSize(s.fontSize, container, s.fontWeight, resolvedFamily);
      let font = `${s.fontWeight} ${resolvedSize}px ${resolvedFamily}`;

      await waitForFonts(font);
      if (currentBuild !== buildId || !alive) return;

      const offscreen = document.createElement('canvas');
      const offCtx = offscreen.getContext('2d', { willReadFrequently: true });
      if (!offCtx) return;

      const content = String(s.text || ' ');
      const maxTextWidth = nextWidth * 0.92;
      offCtx.font = font;
      let metrics = offCtx.measureText(content);
      const measuredWidth = Math.max(1, metrics.width);
      if (measuredWidth > maxTextWidth) {
        resolvedSize = Math.max(18, resolvedSize * (maxTextWidth / measuredWidth));
        font = `${s.fontWeight} ${resolvedSize}px ${resolvedFamily}`;
        await waitForFonts(font);
        if (currentBuild !== buildId || !alive) return;
        offCtx.font = font;
        metrics = offCtx.measureText(content);
      }

      const left = Math.ceil(metrics.actualBoundingBoxLeft || 0);
      const right = Math.ceil(metrics.actualBoundingBoxRight || metrics.width);
      const ascent = Math.ceil(metrics.actualBoundingBoxAscent || resolvedSize * 0.78);
      const descent = Math.ceil(metrics.actualBoundingBoxDescent || resolvedSize * 0.22);
      const padding = Math.max(12, Math.ceil(resolvedSize * 0.08));
      const textWidth = Math.max(1, left + right);
      const textHeight = Math.max(1, ascent + descent);

      offscreen.width = textWidth + padding * 2;
      offscreen.height = textHeight + padding * 2;
      offCtx.clearRect(0, 0, offscreen.width, offscreen.height);
      offCtx.font = font;
      offCtx.textAlign = 'left';
      offCtx.textBaseline = 'alphabetic';
      offCtx.fillStyle = '#ffffff';
      offCtx.fillText(content, padding - left, padding + ascent);

      const imageData = offCtx.getImageData(0, 0, offscreen.width, offscreen.height);
      const targets: Target[] = [];
      const sampleStep = Math.max(2, Math.floor(s.density));

      for (let y = 0; y < offscreen.height; y += sampleStep) {
        for (let x = 0; x < offscreen.width; x += sampleStep) {
          const alpha = imageData.data[(y * offscreen.width + x) * 4 + 3];
          if (alpha > 40) {
            targets.push({
              x: nextWidth / 2 - offscreen.width / 2 + x,
              y: nextHeight / 2 - offscreen.height / 2 + y,
              alpha: alpha / 255
            });
          }
        }
      }

      const maxParticles = Math.max(900, Math.min(5200, Math.floor((nextWidth * nextHeight) / 90)));
      const stride = Math.max(1, Math.ceil(targets.length / maxParticles));
      const selected = targets.filter((_, index) => index % stride === 0);
      const intro = introPending && !reducedMotion;
      introPending = false;

      width = nextWidth;
      height = nextHeight;
      dpr = nextDpr;
      canvas.width = Math.max(1, Math.floor(width * dpr));
      canvas.height = Math.max(1, Math.floor(height * dpr));
      layer.width = canvas.width;
      layer.height = canvas.height;

      bounds.left = Infinity;
      bounds.right = -Infinity;
      bounds.top = Infinity;
      bounds.bottom = -Infinity;
      for (const target of selected) {
        bounds.left = Math.min(bounds.left, target.x);
        bounds.right = Math.max(bounds.right, target.x);
        bounds.top = Math.min(bounds.top, target.y);
        bounds.bottom = Math.max(bounds.bottom, target.y);
      }
      if (!selected.length) {
        bounds.left = bounds.right = width / 2;
        bounds.top = bounds.bottom = height / 2;
      }

      particles = selected.map((target, index) => {
        const seed = ((index * 9301 + 49297) % 233280) / 233280;
        const depth = 0.45 + (((index * 233 + 97) % 1000) / 1000) * 0.9;

        return {
          x: target.x,
          y: target.y,
          startX: target.x,
          startY: target.y,
          targetX: target.x,
          targetY: target.y,
          weight: target.alpha,
          tone: clamp(target.x / Math.max(1, width) + (seed - 0.5) * 0.35, 0, 1),
          seed,
          depth,
          delay: 0,
          ox: 0,
          oy: 0,
          vx: 0,
          vy: 0,
          angle: REST_ANGLE,
          length: 0,
          radius: 0,
          heading: 0,
          startRadius: 0,
          swirl: 0
        };
      });
      bursting = false;

      if (!pointer.active) {
        pointer.x = width / 2;
        pointer.y = height / 2;
        pointer.smoothX = pointer.x;
        pointer.smoothY = pointer.y;
      }

      if (intro) {
        startIntro(true);
      } else {
        gathering = false;
      }

      step(performance.now());
      wake();
    };

    function queueSample(intro: boolean): void {
      if (intro) introPending = true;
      if (sampleFrame) cancelAnimationFrame(sampleFrame);
      sampleFrame = requestAnimationFrame(() => {
        sampleFrame = 0;
        void sampleText();
      });
    }

    const locate = (event: PointerEvent) => {
      const rect = canvas.getBoundingClientRect();
      pointer.x = event.clientX - rect.left;
      pointer.y = event.clientY - rect.top;
    };

    const handlePointerMove = (event: PointerEvent) => {
      locate(event);
      if (!pointer.active) {
        pointer.smoothX = pointer.x;
        pointer.smoothY = pointer.y;
      }
      pointer.active = true;
      wake();
    };

    const handlePointerLeave = () => {
      pointer.active = false;
      wake();
    };

    const handlePointerEnter = (event: PointerEvent) => {
      handlePointerMove(event);
      if (settingsRef.current?.trigger === 'hover') startIntro(false);
    };

    const handlePointerDown = (event: PointerEvent) => {
      const s = settingsRef.current;
      if (!s || s.trigger === 'click' || !s.clickBurst || reducedMotion) return;
      const rect = canvas.getBoundingClientRect();
      burst(event.clientX - rect.left, event.clientY - rect.top);
    };

    const handleClick = () => {
      if (settingsRef.current?.trigger === 'click') startIntro(false);
    };

    const handleReduceMotionChange = (event: MediaQueryListEvent) => {
      reducedMotion = event.matches;
      if (reducedMotion) {
        gathering = false;
        bursting = false;
        particles.forEach(particle => {
          particle.x = particle.targetX;
          particle.y = particle.targetY;
          particle.ox = 0;
          particle.oy = 0;
          particle.vx = 0;
          particle.vy = 0;
        });
      }
      wake();
    };

    motionQuery?.addEventListener?.('change', handleReduceMotionChange);
    canvas.addEventListener('pointerenter', handlePointerEnter);
    canvas.addEventListener('pointermove', handlePointerMove);
    canvas.addEventListener('pointerleave', handlePointerLeave);
    canvas.addEventListener('pointerdown', handlePointerDown);
    canvas.addEventListener('click', handleClick);

    const resizeObserver = new ResizeObserver(() => {
      if (sizeKey() !== requestedSize) queueSample(false);
    });
    resizeObserver.observe(container);

    const intersectionObserver = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      wake();
    });
    intersectionObserver.observe(container);

    const themeObserver = new MutationObserver(wake);
    for (const node of [document.documentElement, document.body]) {
      if (node) themeObserver.observe(node, { attributes: true, attributeFilter: ['class', 'style', 'data-theme'] });
    }
    const schemeQuery = window.matchMedia?.('(prefers-color-scheme: dark)');
    schemeQuery?.addEventListener?.('change', wake);

    void sampleText();

    return () => {
      alive = false;
      buildId += 1;
      wakeRef.current = () => {};
      resizeObserver.disconnect();
      intersectionObserver.disconnect();
      themeObserver.disconnect();
      schemeQuery?.removeEventListener?.('change', wake);
      motionQuery?.removeEventListener?.('change', handleReduceMotionChange);
      canvas.removeEventListener('pointerenter', handlePointerEnter);
      canvas.removeEventListener('pointermove', handlePointerMove);
      canvas.removeEventListener('pointerleave', handlePointerLeave);
      canvas.removeEventListener('pointerdown', handlePointerDown);
      canvas.removeEventListener('click', handleClick);
      if (raf) cancelAnimationFrame(raf);
      if (sampleFrame) cancelAnimationFrame(sampleFrame);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className={`relative isolate block h-full min-h-[240px] w-full overflow-hidden touch-pan-y ${className}`.trim()}
      style={style}
    >
      <canvas ref={canvasRef} className="absolute inset-0 block h-full w-full" aria-hidden="true" />
      <span className="sr-only">{text}</span>
    </div>
  );
};

